programs.sol:
"""A mostly current-token, lexical/formatting detector.

Conversation and tool markup produce the largest responses. A few explicitly
listed temporal, spatial, bonding and comprehension words are also positive.
Bee/honey words and private-game-server advertising form separate spikes.
The ordinary letter-token background grows with vocabulary index, used as
a coarse rarity proxy, with adjustments for capitalization and writing system. This captures
broad trends, not every word's individual response. The conversation opener
is slightly weaker at the start of a document.
"""
READS = ()

CONTROL_MARKUP = {
    '<|im_end|>': 3.75,
    '<|im_start|>': 2.50,
    '<|endoftext|>': -0.03,
    '<tool_call>': 2.50,
    '</tool_call>': 2.81,
    '<tool_response>': 1.78,
    '</tool_response>': 2.13,
    '<think>': 2.84,
    '</think>': 2.51,
}

# These are selected lexical families, not rules for all related words.
WORD_FAMILIES = (
    ({'now', 'always', 'often', 'sometimes'}, 0.80),
    ({'cross', 'across', 'beyond', 'toward'}, 0.94),
    ({'around', 'near', 'behind', 'towards'}, 0.60),
    ({'linear', 'straight', 'circular', 'round', 'loop'}, 0.75),
    ({'relationship', 'relationships', 'together', 'altogether',
      'bond', 'bonds'}, 0.88),
    ({'understand', 'understanding', 'understood',
      'solution', 'solutions'}, 0.77),
)


def token_value(token, token_id):
    if token in CONTROL_MARKUP:
        return CONTROL_MARKUP[token]
    word = token.strip()
    if not word:
        # Horizontal padding, as opposed to ordinary indentation/newlines.
        return (min(1.4, max(0.0, 0.028 * (len(token) - 32)))
                if '\n' not in token else 0.0)
    if word.isdecimal():
        return 0.0
    for members, value in WORD_FAMILIES:
        if word.lower() in members:
            return value
    if '蜂' in word:                  # bee, honeybee, honey
        return 2.2
    if '私服' in word or word == '单职业':
        return 3.2                    # private game servers / game variants
    if word in {'新开', '合击'}:
        return 1.45                   # new-server / combined-attack jargon
    if word == '新开传奇':
        return 2.2
    if word == '《':
        return 1.17                   # opening book-title bracket
    if word in {'✓', '✗'}:
        return 0.68                   # check/cross status marks
    if word == 'ſ':
        return 0.68                   # historical long s
    if word == '<<':
        return 0.68                   # left shift / stream insertion
    if word.startswith('/*'):
        return 0.57                   # block comment opening
    if word.endswith('{"'):
        return 0.46                   # JSON object/key opening
    if word.startswith('\\x'):
        return 0.35                   # escaped byte fragments
    if '\ufffd' in word:
        return 0.28                   # incomplete byte-level character

    letters = ''.join(c for c in word if c.isalpha())
    n = len(letters)
    if not letters:
        return 0.10 * min(7, max(0, len(word) - 2))
    rarity = 0.0000025 * min(token_id, 150000)
    spaced = token.startswith(' ')
    if letters.isascii():
        if not (letters.islower() or letters.isupper() or letters.istitle()):
            return rarity + (0.55 if spaced else 0.35)  # mixed-case identifier
        if n >= 4 and letters.istitle() and spaced:
            return rarity + 0.06
        if n >= 3 and letters.isupper() and spaced:
            return rarity + 0.03
        return rarity - (0.015 if spaced else 0.08)
    if any('\u0600' <= c <= '\u06ff' for c in letters):
        return rarity + (0.24 if spaced else -0.18)      # Arabic
    if any('\u4e00' <= c <= '\u9fff' for c in letters):
        return rarity - 0.16 + 0.05 * min(n, 4)         # Han characters
    if any('\u0400' <= c <= '\u04ff' for c in letters):
        return rarity + (0.02 if spaced and n >= 3 else -0.13)
    if any('\uac00' <= c <= '\ud7af' for c in letters):
        return rarity + (-0.04 if spaced else -0.24)     # Hangul
    if any('\u3040' <= c <= '\u30ff' for c in letters):
        return rarity - (0.05 if n >= 2 else 0.20)       # Japanese kana
    if any('\u0e00' <= c <= '\u0e7f' for c in letters):
        return rarity + 0.02                           # Thai
    return rarity - 0.06


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = (prefix.position == 0 or
                    prefix.document_ids[-1] != prefix.document_ids[-2])
    if token == '<|im_start|>' and new_document:
        return None, 2.23
    return None, float(token_value(token, prefix.token_ids[-1]))

programs.luna:
"""Predict large responses to chat/tool markers, then use token shape as a
coarse proxy for the component's smaller lexical and script-sensitive responses.
"""

READS = ()

MARKER_VALUES = {
    "<|im_end|>": 3.7,
    "<|im_start|>": 2.5,
    "</tool_call>": 2.8,
    "<tool_call>": 2.5,
    "</tool_response>": 2.1,
    "<tool_response>": 1.8,
    "<think>": 2.9,
    "</think>": 2.6,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKER_VALUES:
        return None, MARKER_VALUES[token]
    if token == "<|endoftext|>":
        return None, -0.04
    if token.startswith("<|") and token.endswith("|>"):
        return None, 1.8
    if token.startswith("<tool_") or token.startswith("</tool_"):
        return None, 1.8

    word = token.strip()
    if "\ufffd" in word:
        return None, 0.26
    if not word:
        return None, 0.0

    cjk = any(0x3400 <= ord(char) <= 0x9FFF for char in word)
    if cjk:
        return None, 0.16

    letters = all(char.isalpha() for char in word)
    non_ascii = any(not char.isascii() for char in word)
    if non_ascii:
        if word[0].isupper():
            return None, 0.06
        if letters and len(word) >= 4:
            return None, 0.20
        return None, 0.07

    if letters:
        long = len(word) >= 4
        if word[0].isupper():
            return None, 0.17 if long else 0.01
        return None, 0.045 if long else -0.005

    return None, 0.08 if len(word) >= 4 else 0.0

programs.sol:
"""Estimate a singular-indefinite signal, chiefly on English a/an tokens.

Appositional punctuation and provision verbs strengthen it; possession,
selection and common object-taking verbs weaken it. Letter fragments and
recent formula/code symbols are downweighted. Some other languages'
articles and 'one + classifier' expressions also get positive estimates.
Unrecognized tokens get zero. State resets at each document boundary.
"""
READS = ()

ENGLISH = {'a': 1.05, 'an': 1.18, 'A': 0.30, 'An': 1.35, 'AN': 0.55}
DOCUMENT_START = {'a': 1.90, 'an': 2.24, 'A': 2.46, 'An': 3.23, 'AN': 0.55}
GERMAN = {
    'ein': 0.67, 'eine': 1.12, 'einer': 0.69,
    'eines': 0.53, 'einen': 0.39, 'einem': 0.26,
}
CLASSIFIERS = set('个個种種位名场場座段件条條只隻本张張家项項')

# Named grammatical/meaning classes, not a token-ID lookup table.
EXISTENCE_POSSESSION = set(
    'have has had having get gets got getting exists exist there'.split()
)
SELECTION = set('pick picks picked choose chooses choosing chose find finds finding'.split())
PROVISION = set('provide provides provided providing offer offers offered offering'.split())
OBJECT_VERBS = set(
    'make makes made making take takes took taking do does doing '
    'need needs needed write writes writing give gives given obtain'.split()
)
USAGE_ACCOMPANIMENT = set('use uses used using for with within without'.split())
RESTRICTING_WORDS = set('if when not just even'.split())
WORD_EFFECTS = (
    (EXISTENCE_POSSESSION, -1.10), (SELECTION, -0.95),
    (PROVISION, 1.40), (OBJECT_VERBS, -0.65),
    (USAGE_ACCOMPANIMENT, -0.55), (RESTRICTING_WORDS, -0.55),
    ({'and', 'but'}, 0.85),
    ({'or', 'into', 'during', 'under', 'became'}, 0.30),
    ({'be', 'being'}, -0.35),
)


def following_word_effect(previous, before_previous, word):
    """Local punctuation and grammar change the ordinary article estimate."""
    p = previous.strip()
    lower = p.lower()
    if p.endswith((',', ';', ':', '—', '–')):
        return 1.70 if word in {'a', 'an'} else 1.25
    if p.endswith('-'):
        return 1.80 if word in {'a', 'an'} else 0.85
    if p.endswith(('.', '!', '?')):
        return 0.65 if word == 'a' else 0.80
    if p == "'s":
        return -0.55
    for words, effect in WORD_EFFECTS:
        if lower in words:
            return effect
    if lower in {'is', 'are', 'was', 'were'}:
        if before_previous.strip().lower() == 'there':
            return 0.25 - ENGLISH[word]
        return 0.30 if lower in {'was', 'were'} else 0.15
    if lower in {'sin', 'cos', 'tan', 'log', 'ln'}:
        return -0.25 - ENGLISH[word]
    return -0.55 if any(c in p for c in '=+$\\') else 0.0


def bare_letter_value(word, previous):
    """Without leading whitespace, a/A is often a fragment or variable."""
    if word in {'an', 'An', 'AN'}:
        return {'an': 0.10, 'An': 1.65, 'AN': 0.0}[word]
    if '\n' in previous:
        return 1.35
    if previous and previous.isspace():
        return 1.25
    if previous.endswith(('(', '[', '"', "'", '“', '‘')):
        return 1.0
    p = previous.strip()
    if p[-1:].isalpha():
        return -0.05
    if p[-1:].isdigit():
        return 0.30 if word == 'a' else -0.05
    return 0.15


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, recent = '', '', ''
        first = True
    else:
        _, previous, before_previous, recent = carry
        first = False
    word = text.strip()
    spaced = text[:1].isspace()
    value = 0.0
    if word in ENGLISH:
        value = bare_letter_value(word, previous)
        if spaced:
            value = ENGLISH[word] + following_word_effect(previous, before_previous, word)
            if any(c in recent for c in '$\\_{'):
                value -= 0.35
        if first:
            value = 1.05 if spaced and word == 'A' else DOCUMENT_START[word]
        value = max(-0.30, value)
    elif word in {'-a', '-an', '—a', '—an'}:
        value = 2.50 if word.startswith('—') else (1.30 if word.endswith('an') else 0.75)
    elif spaced and word.lower() in GERMAN:
        value = GERMAN[word.lower()]
        if previous.strip().endswith((',', ';', ':', '—', '–')):
            value += 0.60
    elif spaced and word.lower() in {'een', 'uma', 'một'}:
        value = {'een': 0.85, 'uma': 0.47, 'một': 0.49}[word.lower()]
    elif word in {'One', 'Another'}:
        value = 0.60
    elif spaced and word == 'another':
        value = 0.26
    elif word in {'一个', '一個'}:
        value = 0.83
    elif any('一' + c in word for c in CLASSIFIERS):
        value = -0.15 if word.startswith('有') else (0.70 if word.startswith('是') else 1.40)
    elif word == '了一':
        value = 1.46
    # Fixed-size recent context, rather than rereading the whole prefix.
    return (doc, text, previous, (recent + text)[-160:]), float(value)

programs.haiku:
"""Weather and precipitation words.

This component writes a "this word is about weather or snow" signal into the residual
stream. It reads only the current token, not the context. Snow and rain words give the
strongest signal (the Chinese character for snow strongest of all), storm, wind and cloud
words a medium one, and nature, sky and season words a weak one. Everything else is 0.
"""

READS = ()

# Snow and rain words, and the Chinese characters for snow, rain, dew, frost and hail.
SNOW_RAIN = {"snow", "snowy", "snowflake", "snowfall", "rain", "rains", "rainy", "rainfall",
             "drizzle", "frost", "hail", "sleet", "雨", "下雨", "霜", "雹", "露"}
# Other weather and storm words.
WEATHER = {"storm", "storms", "weather", "wind", "winds", "breeze", "cloud", "clouds", "cloudy",
           "thunder", "thunderstorm", "lightning", "hurricane", "tornado", "blizzard", "shower",
           "showers", "mist", "fog", "precipitation", "drought", "dew", "flood",
           "风", "風", "云", "雲", "雷", "晴"}
# Nature, sky and season words.
NATURE = {"sun", "sunlight", "sunshine", "moon", "sky", "sand", "fire", "smoke", "ice", "water",
          "sea", "grass", "mud", "dust", "soil", "winter", "summer", "autumn", "river", "tree",
          "trees", "火", "水", "草", "海", "沙", "山"}

def value(token):
    word = token.strip().lower()
    if word == "雪":
        return 8.0
    if word in SNOW_RAIN:
        return 4.5
    if word in WEATHER:
        return 1.5
    if word in NATURE:
        return 0.7
    return 0.0

def step(carry, prefix, upstream):
    return carry, value(prefix.token_strings[-1])

programs.sol:
"""A negative lexical signal for secondary or auxiliary roles and additions.

Strong examples are secondary, auxiliary, minor, and Chinese assistance
characters. Related supporting, peripheral, artificial, or temporary things
produce weaker negatives. Unrecognized tokens get zero: this intentionally
leaves the component's many small, less coherent responses unexplained.
Only a short word tail is retained, to recognize split spellings.
"""
READS = ()

STRONG = {
    'secondary': -2.75, 'auxiliary': -2.55, 'minor': -1.32,
    'tertiary': -1.25, 'peripheral': -1.2, 'supplementary': -1.1,
    'artificial': -1.02, 'additional': -0.91, 'augmented': -1.35,
    'augment': -0.85, 'accessory': -0.94, 'adjunct': -0.73,
    'suffix': -0.69, 'indirect': -0.67, 'complementary': -0.6,
}
SUPPORTING = set('''
    dual alternate intermediate helper subsidiary assisted assisting
    supplement supplemental supplemented supplements augmentation
    accessories temporary passive overlay overlays subordinate decorative
    decorator middleware sideline surrounding
'''.split())
WEAKER = set('''
    extra alternative adjacent assist assistant enhance enhanced
    minimal primary further complement weak peripheral
'''.split())
# Assistance/subordinate/additional/peripheral terms in other languages.
TRANSLATIONS = {
    '辅': -3.6, '輔': -3.7, '辅助': -3.3, '佐': -2.2,
    '副': -0.95, '二次': -1.45, '额外': -0.76, '外围': -0.77,
    '弱': -0.6, '旁': -0.45, '周边': -0.46, '周围': -0.55,
    'дополн': -1.01, 'yardımcı': -0.73, 'phụ': -1.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip(' \n\r\t._-/(')
    lower = word.lower()
    value = STRONG.get(lower, TRANSLATIONS.get(lower, 0.0))
    if lower not in STRONG and lower not in TRANSLATIONS:
        if lower in SUPPORTING:
            value = -0.48
        elif lower in WEAKER:
            value = -0.24

    # Different token spellings of these words have different strengths.
    if lower == 'secondary' and not raw[:1].isspace():
        value = -2.48 if word[:1].isupper() else -2.17
        if raw[:1] in '.-':
            value = -1.87
    elif lower == 'auxiliary' and word[:1].isupper():
        value = -2.04
    elif lower == 'minor' and not raw[:1].isspace() and word.islower():
        value = -0.9
    elif lower == 'artificial' and word[:1].isupper():
        value = -1.26
    elif lower == 'supplementary' and word[:1].isupper():
        value = -0.82
    elif lower == 'additionally':
        value = -0.1 if word[:1].isupper() else -0.42
    elif lower == 'helper' and word[:1].isupper():
        value = -0.2

    spelling = (tail + word if raw[:1].isalpha() else word).lower()[-24:]
    # Only the final fragment, not every token of the assembled word, fires.
    if lower == 'isted' and spelling.endswith('assisted'):
        value = -0.93
    elif lower == 'illary' and spelling.endswith('ancillary'):
        value = -0.81
    elif lower == 'ificial' and spelling.endswith('artificial'):
        value = -1.12
    elif lower == 'plementary' and spelling.endswith(
            ('supplementary', 'complementary')):
        value = -1.01
    elif lower == 'ipheral' and spelling.endswith('peripheral'):
        value = -1.03
    elif lower == 'iliary' and spelling.endswith('auxiliary'):
        value = -2.0
    elif lower == 'uffix' and spelling.endswith('suffix'):
        value = -0.88
    return (doc, spelling), float(value)

programs.luna:
"""Mark added, auxiliary, secondary, or peripheral terms with a negative activation."""

READS = ()

VERY_STRONG = {"secondary", "auxiliary", "辅", "佐"}
CLEAR = {
    "additional", "supplementary", "minor", "artificial", "augmented",
    "augment", "peripheral", "额外", "副", "二次", "дополн",
}
RELATED = {
    "additionally", "subsidiary", "subordinate", "intermediate", "alternate",
    "alternative", "temporary", "passive", "weak", "lesser", "helper",
    "assisted", "assist", "assistance", "accessory", "accessories", "overlay",
    "overlays", "supplement", "supplements", "supplemental", "supplemented",
    "complementary", "plementary", "suffix", "uffix", "augmentation", "dual",
    "extra", "indirect", "side", "second", "pseudo", "periphery", "旁", "弱",
    "附加", "artificially",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in VERY_STRONG:
        return None, -2.5
    if word in CLEAR:
        return None, -1.0
    if word in RELATED:
        return None, -0.5
    return None, 0.0

programs.sol:
"""A lexical approximation to a multilingual grammatical-marker response.

Japanese/Korean topic and subject particles and short Chinese questions,
aspect markers, and predicates receive negative scores. Chinese grammatical
combinations add character-class scores, diluted by their length. Only
the listed grammatical alphabet is split; lexicalized exceptions stay whole.
Some case markers receive small
positive scores. English additive words and reflexives are weakly negative.
This ignores context and the component's many finer lexical differences.
"""
import math

READS = ()
SIMPLIFY = str.maketrans('這還沒嗎麼麽個種們誰來給過時為裡會',
                        '这还没吗么么个种们谁来给过时为里会')

CHINESE_CLASSES = (
    ('又没', -0.93),                 # repetition / absence
    ('都就再还了', -0.68),           # scope, continuation, aspect
    ('有是要得', -0.53),             # core predicates and result marker
    ('这那', -0.47),                 # demonstratives
    ('才跟给来成看拿完打吃穿在越加剩', -0.33),  # predicates / relations
    ('不能好着超快真太很多可也到过去先该会', -0.24),  # weaker modifiers
    ('你我他她它自己', -0.06),       # pronouns
)
CHAR_SCORES = {c: score for chars, score in CHINESE_CLASSES for c in chars}
GRAMMAR_CHARS = set(CHAR_SCORES) | set(
    '的一些个种点里人们一二三几位次下上去出会把让和与而但则为'
)
QUESTIONS = {
    '怎', '怎么', '怎么样', '什么', '啥', '哪', '哪里', '哪儿',
    '哪个', '有什么', '有没有', '怎么办', '是什么', '这么',
    '有哪些', '多少钱',
}
MILD_QUESTIONS = {'如何', '多久', '多少', '何时', '何', '谁', '哪些'}
# These lexicalized compounds should not add the scores of their characters.
LEXICALIZED = {
    '为了', '但是', '可是', '可能', '完成', '得到', '获得',
    '不过', '以及', '所以', '因此', '那么',
}
REFLEXIVES = {
    'self', 'myself', 'yourself', 'himself', 'herself', 'itself',
    'ourselves', 'yourselves', 'themselves',
}


def chinese(word):
    word = word.translate(SIMPLIFY)
    if word in QUESTIONS:
        return -0.99
    if word in MILD_QUESTIONS:
        return -0.46
    if word in {'吗', '啊'}:
        return -0.64
    if word in {'这个', '那个', '这种', '那种'}:
        return -0.67
    if word in {'呢', '么'}:
        return -0.32
    if word in {'没有', '不敢', '不行'}:
        return -0.60
    if word == '自己':
        return -0.53
    if word in {'可以', '能够', '应该', '应当', '能否'}:
        return -0.22
    if word in LEXICALIZED or word in {'吧', '呀', '啦'}:
        return 0.02
    if word in {'的', '将', '被'}:
        return 0.07
    if len(word) <= 4 and all(c in GRAMMAR_CHARS for c in word):
        score = sum(CHAR_SCORES.get(c, 0.0) for c in word)
        score = score / math.sqrt(len(word)) + 0.01
        if len(word) > 1 and word[0] in '都还才又也这':
            score -= 0.11
        return score
    if len(word) <= 3 and word.endswith('了'):
        if len(word) == 2 and word[0] in '哭笑坏死累瘦胖吃走':
            return -0.59
        return -0.30
    return 0.01


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    value = 0.0
    if word and all('\u4e00' <= c <= '\u9fff' for c in word):
        value = chinese(word)
    elif any('\u3040' <= c <= '\u309f' for c in word):
        value = 0.05
        if word in {'は', 'が'}:
            value = -0.77
        elif word == 'も':
            value = -0.46
        elif word in {'には', 'では', 'のが'}:
            value = -0.23
        elif word.endswith(('は', 'が')):
            value = 0.05 - 0.44 / math.sqrt(len(word) - 1)
        elif word.endswith('も'):
            value = -0.05
        elif word in {'って', 'しか', 'なんて', 'ばかり', 'たら', 'とか'}:
            value = -0.24
        elif word in {'に', 'から', 'へ'}:
            value = 0.17
    elif word and all('\uac00' <= c <= '\ud7af' for c in word):
        value = 0.02
        if word in {'이', '가'}:
            value = -0.36 if raw[0].isspace() else -0.68
        elif word in {'은', '는', '도'}:
            value = -0.28 if raw[0].isspace() else -0.53
        elif len(word) <= 3 and word.endswith(('이', '가', '은', '는', '도')):
            value = -0.15
        elif word in {'에', '에서', '로', '부터', '까지'}:
            value = 0.15
    elif raw[:1].isspace() and word.isascii() and word.isalpha():
        word = word.lower()
        if word in {'also', 'again', 'too', 'either', 'same'}:
            value = -0.064
        elif word in REFLEXIVES:
            value = -0.086
    return None, float(value)

"""Detect standalone horizontal tabs, rather than any text containing a tab.

Single-tab tokens have a strong positive response, especially near the start
of a document. Numeric line labels reduce it. Merged runs of tabs respond
much less, and tab/newline tokens have only a small positive response.
Other token activations are approximated by zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == doc else 0
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if position else ''
    value = 0.0
    if token and set(token) == {'\t'}:
        count = len(token)
        if count == 1:
            value = 0.78 + 0.18 * math.exp(-position / 40)
            if position == 0:
                value = 0.921
        elif count == 2:
            value = 0.18
        elif count == 3:
            value = 0.075
        if previous.strip().isdigit():
            value -= 0.17 if count == 1 else 0.14 if count == 2 else 0.12
    elif token in ('\t\n', '\t\r\n'):
        value = 0.06
    return (doc, position), float(value)

"""Detect the spelling 'end', with a weaker response to related nd endings.

The strongest cues are short end-roots and end-fragments inside words.
Long words, inflections, and common lexical exceptions weaken this response.
'return' and 'respond' are additional cues; a few past tenses and non-Latin
fragments are included too. The preceding character distinguishes a fragment
inside a word from the same letters at a word boundary. These are approximate
spelling rules, not a detector of the end of a document.
"""
READS = ()


def end_strength(word, boundary, attached, original):
    before, after = word.split('end', 1)
    if 'friend' in word or 'commend' in word or 'calendar' in word:
        return 0.15
    if 'render' in word:
        return 1.2 if not word.endswith('ed') else 0.75
    if 'gender' in word or 'nintendo' in word:
        return 0.7
    if word.startswith('end') and not boundary and original[:1].isalpha():
        value = (3.95 if not after else 3.4) if attached else 2.3
        if original.isupper() and not after:
            value += 1.1
        elif original[:1].isupper():
            value = 1.8
        if after in ('e', 'en', 'o', 'or'):
            if after == 'o':
                value *= 0.8
            value *= 0.73
        elif after == 'l':
            value = 1.2
        elif after not in ('', 's', 'er', 'ers', 'ed', 'ing', 'a', 'as', 'i', 'ra'):
            value *= 0.4
        return value
    if before in ('t', 'v', 'h', 'w'):
        value = 4.4
    elif before == 'p':
        value = 5.3
    elif before in ('b', 'l', 'm', 'r'):
        value = 3.6
    elif before in ('sp', 'att', 'app'):
        value = 3.3
    elif before in ('susp', 'desc', 'pret') and after in ('', 's', 'ed', 'ing'):
        value = 2.9
    elif before in ('', 's', 'ext'):
        value = 1.7 if before != 's' else 1.95
    else:
        value = 2.1 if len(before) <= 3 else 1.0
    if word.startswith('append'):
        value = 3.3 if boundary else 4.0
        if original.startswith('.'):
            value = 2.55
    if after == 's':
        value *= 0.83
    elif after == 'ed':
        value *= 0.77 if before == 'att' else 0.43
    elif after == 'ing':
        if before == 'v':
            return 1.25
        value *= 1.05 if before == 'sp' else 0.8
        if before == 'dep':
            value *= 0.5
    elif after:
        value *= 0.42 if before in ('t', 'p', 'v', 'w') else 0.62
    return value


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    attached = bool(prev[-1:].isalpha() and text[:1].isalpha())
    word = text.lower().strip(' \t\r\n.,;:!?_-/\\()[]{}\'"`=<>$')
    value = 0.0
    if text.startswith('<|'):
        pass
    elif 'return' in word:
        value = 0.66 if word.endswith('ed') else 0.9
        if word.endswith('s'):
            value = 0.8
    elif 'end' in word:
        value = end_strength(word, text[:1].isspace(), attached, text.strip())
        if word == 'end' and text[:1].isspace():
            value = 1.9 if prev.lower().strip() == 'the' else 1.5
    elif word.startswith('respond'):
        value = 1.0
    elif 'nd' in word:
        before, after = word.split('nd', 1)
        value = 0.8 if before.endswith('a') else 0.5
        if len(before) == 1 and before in 'áàâäåãéèêëíìîïóòôöõúùûü':
            value = 1.7
        if len(before) > 3:
            value *= 0.3
        if len(after) > 2:
            value *= 0.25
        if word in ('nd', 'and', 'ind', 'ond', 'und'):
            value = 0.8
            if word == 'nd':
                value = 1.9 if attached else 1.2
            elif word == 'and':
                value = 1.45 if attached else 0.25
                if text[:1].isspace():
                    value = 0.0
                elif text[:1].isupper():
                    value = 1.0 if text.isupper() else 0.2
        if word == 'und' and text[:1].isspace():
            value = 0.1
        if word in ('pandas', 'andas', 'andy'):
            value = 1.4
        if word in ('find', 'found', 'under', 'second', 'around',
                    'window', 'index', 'command', 'standard', 'condition',
                    'handle', 'random', 'poland', 'england', 'understanding'):
            value = 0.0
    elif word in ('spent', 'sent', 'went', 'lent', 'bent'):
        value = {'spent': 1.87, 'sent': 0.7, 'went': 0.5,
                 'lent': 1.2, 'bent': 0.85}[word]
    elif word in ('ent', 'vent'):
        value = 0.28 if word == 'ent' else 1.0
    elif 'енд' in word:
        value = 3.2 if word == 'енд' else 1.5
    elif word in ('анд', 'ند'):
        value = 1.5
    return (doc, text), float(value)

programs.luna:
"""Predict a small positive signal for 'end', 'nd', and 'return' spellings.

The component's strongest harvested examples often contain these letter
sequences. This conservative lexical sketch reads only the current token.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()
    if "return" in word:
        value = 0.45
    elif "end" in word:
        value = 0.7
    elif "nd" in word:
        value = 0.3
    else:
        value = 0.0
    return None, value

"""Estimate activity at the end of a parenthetical or bracketed expression.

High-importance examples often land on closing delimiters, so this assigns a
small positive estimate to a closing bracket and zero to other token endings.
"""

READS = ()

_CLOSING_MARKS = {
    ")": 0.68,
    "]": 0.90,
    "}": 0.90,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    for char in reversed(token):
        if char in _CLOSING_MARKS:
            return None, float(_CLOSING_MARKS[char])
        if char.isalnum() or char.isspace():
            break
    return None, 0.0

programs.sol:
"""An immediate-morpheme-context approximation, not a grammatical parser.

Japanese kana tend to be positive. Many inflectional fragments after
verb-like stems receive negative scores. Korean endings and `void` declarations have
similar context-sensitive contrasts. Smaller rules cover commas, particles,
and a few conventional affix/partitive families. Scores are rounded
training means; unseen classes default near zero.
State is the previous token, a declaration modifier, and eight tokens of
Japanese-script evidence; it resets at document boundaries. Many lexical
and finer contextual responses remain unexplained.
"""
READS = ()

E_ROW = frozenset('えけげせぜねへべぺめれ')
I_ROW = frozenset('いきぎしじちぢにひびぴみり')
KANJI_STEMS = frozenset('見出来寝似得')

# Scores: after e-row, i-row, kanji stem, or other ending, respectively.
# Rows group Japanese ending fragments, and the single syllable ま.
ENDING_GROUPS = (
    ('た たら たり たく', (-0.52, -0.09, 0.32, 2.14)),  # ta-initial endings
    ('て', (-0.88, -0.92, -0.17, 1.43)),  # conjunctive
    ('ます', (-0.77, -0.56, 0.26, 1.62)),  # polite
    ('ました', (-0.04, 0.37, 0.97, 1.61)),  # polite_past
    ('ません', (-0.59, -0.5, -0.01, 0.29)),  # polite_negative
    ('ましょう', (-0.73, -0.81, 0.0, 0.0)),  # polite_volitional
    ('たい', (-0.55, -0.41, 0.61, 1.63)),  # desire
    ('る れる', (-0.65, -0.69, -0.24, 0.38)),  # nonpast verb endings
    ('られる られない', (-0.79, -0.74, 0.06, 0.34)),  # passive/potential
    ('ない', (-0.68, -0.21, 0.0, 0.41)),  # negative
    ('ず', (-1.32, -1.15, -0.65, 0.21)),  # negative connective
    ('ば', (-0.51, -0.1, 0.0, 1.33)),  # conditional
    ('ま', (-0.16, 0.02, 0.0, 1.08)),  # syllable ma
    ('よう', (-0.86, -0.01, -0.09, 0.97)),  # volitional
    ('つつ', (-1.76, -1.82, 0.0, 0.0)),  # simultaneous
    ('やすい やすく', (-1.37, -1.04, -0.14, -0.42)),  # easy
    ('方', (-1.78, -1.31, -0.7, -0.19)),  # way/manner
)
ENDING_SCORES = {
    form: rates for forms, rates in ENDING_GROUPS for form in forms.split()
}
KOREAN_BOUND = frozenset('고 기 게 지만 며 던 므로'.split())
KOREAN_SHORT = frozenset('지 면 자 나 려'.split())
KOREAN_STEMS = frozenset('하되보가오주시리르쓰이나크내키추많찾찍읽')
LATIN_A_SUFFIXES = frozenset(
    'ar an am at ate ation ations ator ators able aba amos ados '
    'ada ado ador adora acional'.split()
)


def hiragana(c):
    return '\u3041' <= c <= '\u3096'


def activation(s, previous, modifier, japanese_recent):
    word, prev = s.strip(), previous.strip()
    end = prev[-1:] or ' '
    if word == 'void':
        if prev == 'static':
            return -0.62 if modifier else -0.11
        return {'public': -1.05, 'private': -0.42,
                'protected': -0.53}.get(prev, -0.05)
    if word == 'public':
        return 0.08
    if word == 'of' and s != word:
        if prev.lower() in ('one', 'each', 'most', 'any', 'top', 'best'):
            return -0.10
        if prev.lower() in ('kind', 'kinds', 'type', 'types', 'sort', 'sorts'):
            return -0.08
        if prev.lower() in ('pair', 'pairs', 'couple', 'set', 'variety'):
            return 0.10
    if word == '、':
        if hiragana(end):
            strong = end in 'しりち' or prev.endswith(('あり', 'なく'))
            return -0.83 if strong else -0.39
        return -0.30 if japanese_recent else -0.02
    if s != word:
        return -0.004
    if word in ENDING_SCORES:
        if end in E_ROW:
            stem = 0
        elif end in I_ROW:
            stem = 1
        elif end in KANJI_STEMS:
            stem = 2
        else:
            stem = 3
        return ENDING_SCORES[word][stem]
    if word and all(hiragana(c) for c in word):
        if word in ('に', 'の', 'には', 'にも', 'では', 'でも', 'のは'):
            return -0.11
        if word in ('と', 'や', 'な'):
            return 0.16
        if word in ('は', 'が', 'を', 'も', 'で'):
            return 0.01
        if word in ('よ', 'ね', 'か'):
            return 0.72
        return 0.38 if len(word) == 1 else 0.14 if len(word) == 2 else 0.005
    if word in KOREAN_BOUND or word in KOREAN_SHORT:
        bound = word in KOREAN_BOUND
        if '\uac00' <= end <= '\ud7a3':
            coda = (ord(end) - 0xac00) % 28
            # Rieul-ending stems and past-tense ssang-siot also count.
            if end in KOREAN_STEMS or coda in (8, 20):
                return -1.57 if bound else -0.99
            if coda == 0:
                return -0.21 if bound else 0.09
            return -0.60 if bound else 0.14
        return -0.26 if bound else -0.11
    if word in ('에', '는', '을', '를', '어'):
        return -0.19
    if word in ('атель', 'ательная', 'ательно', 'ательный'):
        return -0.34
    if word in ('ать', 'аться', 'ал', 'ала', 'али',
                'ав', 'ает', 'ают'):
        return 0.10
    if word in ('ative', 'ary', 'atory', 'atives'):
        return -0.11
    if word in ('ador', 'adora', 'adores', 'adoras'):
        return 0.21
    if word in ('aba', 'amos'):
        return 0.29
    if word in LATIN_A_SUFFIXES:
        return -0.23 if end.lower() == 'i' else 0.06
    return -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, modifier, recent = '', '', 0
    else:
        _, previous, modifier, recent = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, modifier, bool(recent))
    word = s.strip()
    if word in ('public', 'private', 'protected'):
        modifier = word
    elif word != 'static':
        modifier = ''
    recent = ((recent << 1) | int(any(hiragana(c) for c in s))) & 255
    return (doc, s, modifier, recent), float(value)

programs.haiku:
"""Layer-0 MLP unit 5960 (down_proj), a word-fragment unit for Japanese and Korean.

Reads only the newest token. It is a token-level detector:
- Japanese kana pieces that inflect or extend a verb or adjective (た, ば, ま, たら,
  ます, ね, か, よ, よう, し, り, さ ...) push it up; た is the strongest.
- Korean verb and connective endings (게, 느, 지만, 다, 나, 려, 고, 기, 며, 는) push it down.
- The Java keyword " void" and the Japanese comma 、 push it down a little.
Everything else predicts 0. Values are typical activations for each piece.
"""

READS = ()

KANA_VERB_PIECES = {
    "た": 1.2, "ば": 1.0, "ま": 0.9, "たら": 0.8, "ます": 0.7, "よう": 0.8,
    "ね": 0.7, "か": 0.6, "よ": 0.6, "こ": 0.6, "む": 0.6, "せ": 0.6,
    "し": 0.4, "り": 0.4, "き": 0.4, "あ": 0.4, "さ": 0.4, "わ": 0.4,
    "く": 0.4, "い": 0.4, "て": 0.4, "め": 0.4, "ら": 0.4,
}
KOREAN_ENDINGS = {
    "게": -1.2, "느": -1.2, "지만": -1.0, "다": -0.8, "나": -0.5, "려": -0.4,
    "고": -0.35, "기": -0.35, "며": -0.3, "는": -0.3, "에": -0.3,
}
OTHER = {" void": -0.5, "、": -0.2}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in KANA_VERB_PIECES:
        return carry, KANA_VERB_PIECES[tok]
    if tok in KOREAN_ENDINGS:
        return carry, KOREAN_ENDINGS[tok]
    return carry, OTHER.get(tok, 0.0)

programs.sol:
"""Approximate the component's local English phrase responses.

Negative peaks occur on 'make/not sure' and 'be able'. Positive responses
occur on this/that/it after question, conditional, or tentative-clause words.
Whitespace separates whole-word readings from suffixes; capitalization
adjusts clause openings. State keeps one preceding token within a document.
Other lexical responses are left at zero: this is a partial explanation.
The magnitudes are calibrated on training examples, not confidence scores.
"""

READS = ()

QUESTION_STRENGTH = {
    'if': 0.60,
    'whether': 0.85,
    'how': 0.80,
    'why': 0.52,
    'when': 0.42,
    'unless': 0.70,
}
TENTATIVE = {'maybe', 'perhaps', 'suppose', 'assuming', 'consider', 'considering'}
THOUGHT_OR_SPEECH = {'think', 'say', 'feel', 'believe', 'assume'}
REPORTING = {'said', 'says', 'saying', 'thought', 'means', 'meaning', 'mean'}
FACTUAL_CLAUSES = {'show', 'note', 'ensure', 'verify', 'announced'}
BE_FORMS = {'am', 'is', 'are', 'was', 'were', "'m", '’m', "'re", '’re'}
ADJECTIVES = {
    'unable': -0.42,
    'careful': -0.62,
    'afraid': -0.47,
    'unsure': -0.65,
    'certain': -0.12,
    'possible': -0.15,
    'true': -0.09,
    'necessary': 0.13,
    'needed': 0.11,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = old.strip()
    p = previous.lower()
    w = word.lower()
    capital_previous = bool(previous and previous[0].isupper())
    separate = bool(token[:1].isspace())
    value = 0.0

    if w == 'sure':
        if word != 'sure' or not separate:
            value = (-0.34 if word == 'sure' else -0.44) if not separate else -0.62
        elif p in {'make', 'making', 'made', 'makes'}:
            value = -1.90 - 0.07 * capital_previous
        elif p in {'not', "'t", '’t'}:
            value = -1.72
        elif p == 'for':
            value = -0.85
        elif p == 'be':
            value = -1.60 - 0.15 * capital_previous
        elif p in BE_FORMS:
            value = -1.10
        elif p == 'you':
            value = -1.25
        elif p in {'quite', 'really', 'very', 'entirely', 'exactly'}:
            value = -1.40
        else:
            value = -0.65
    elif word == 'able' and separate:
        if p == 'being':
            value = -1.38
        elif p in {'be', 'been', 'not'}:
            value = -0.98
        elif p in BE_FORMS:
            value = -0.71
        else:
            value = -0.60
    elif word in ADJECTIVES and separate:
        value = ADJECTIVES[word]
        if word == 'possible' and p in {'as', 'not', 'if'}:
            value = -0.32
        elif word == 'true' and p in BE_FORMS | {'be'}:
            value = -0.21
    elif word == 'rid' and separate and p in {'get', 'getting', 'got'}:
        value = -0.60
    elif word in {'this', 'that', 'it'} and separate:
        if p in QUESTION_STRENGTH:
            value = QUESTION_STRENGTH[p]
        elif p in TENTATIVE:
            value = 0.50
        elif p in THOUGHT_OR_SPEECH:
            value = 0.36
        elif p == 'hope':
            value = 0.62 if word == 'this' else 0.36
        elif p in {'try', 'tried'}:
            value = 0.58 if word != 'it' else 0.26
        elif p in {'do', 'doing', 'like', 'as'}:
            value = 0.31
        elif p in {'does', 'can', 'could', 'will', 'would', 'should'}:
            value = 0.50 + 0.15 * capital_previous
        elif p in BE_FORMS:
            value = 0.22 + 0.42 * capital_previous
        elif p in {'not', "'t", '’t'}:
            value = 0.40
        elif p == 'given':
            value = 0.26
        elif p in REPORTING:
            value = 0.23
        elif word == 'that' and p in FACTUAL_CLAUSES:
            value = -0.12
        if value:
            value *= {'this': 1.0, 'that': 0.8, 'it': 0.5}[word]
            value += 0.09 * capital_previous
        elif word == 'that' and p in {'so', 'such'}:
            value = -0.12
    elif word == 'of' and separate:
        if p == 'think':
            value = -0.68
        elif p == 'thought':
            value = -0.46
        elif p == 'thinking':
            value = -0.27
    elif word == 'to' and separate and p == 'sure':
        value = -0.33
    elif word == 'if' and separate:
        if p in {'even', 'only', 'as'}:
            value = -0.23
        elif p in {'sure', 'know', 'see'}:
            value = -0.25
    return (doc, token), float(value)

programs.luna:
"""Use a few sampled word cues as small, signed activation estimates."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0

    if word in {"this", "that", "about"}:
        value = {"this": 0.65, "that": 0.48, "about": 0.3}[word]
    elif word in {"sure", "able", "unable", "unsure", "careful"}:
        value = {
            "sure": -1.7,
            "able": -0.8,
            "unable": -0.6,
            "unsure": -0.6,
            "careful": -0.6,
        }[word]
    elif word in {"true", "whether", "rid"}:
        value = {"true": -0.55, "whether": -0.35, "rid": -0.6}[word]
    elif (
        word == "of"
        and len(prefix.token_strings) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
        and prefix.token_strings[-2].strip().lower() in {"think", "thinking"}
    ):
        value = -0.55

    return carry, 0.25 * value

programs.sol:
"""Approximate a multilingual linking/accompaniment and tracking detector.

Strong negative responses mark Chinese 'with/and', Japanese and Korean
linking particles, and English tracking words. English 'to' is negative
mainly after connection words, not as a general infinitive marker. The
numbers are rounded training estimates. Weak responses elsewhere and
finer context-dependent changes are deliberately left out.
"""
READS = ()

LINKING_PARTICLES = {
    # Chinese 'with', 'and', and following someone.
    '跟': -8.4, '跟我': -6.1, '跟他': -7.7, '就跟': -6.8,
    '跟着': -3.0, '紧跟': -3.0, '跟随': -2.1, '跟踪': -1.4,
    '与': -2.75, '與': -2.8, '并与': -2.65, '和': -1.02,
    # Chinese sameness, comparison, and pursuit.
    '同': -1.17, '同一': -0.47, '同一个': -0.52,
    '比': -0.8, '比我': -0.8, '就像': -0.85,
    '追': -1.2, '追踪': -1.5, '追随': -1.0, '追赶': -0.85,
    # Japanese 'with/that', 'together', and 'same as'.
    'と': -0.85, 'とは': -0.9, 'との': -1.5, '」と': -0.87,
    'とも': -0.65, 'と同じ': -1.4, '同じ': -0.37,
    'と共に': -0.94, 'と一緒に': -1.2, 'や': -0.23,
    # Korean 'and/with'.
    '과': -0.93, '와': -0.92,
}

STRONG_CONNECTION = {'related', 'unrelated', 'connected', 'linked'}
RELATING = {'relate', 'relates', 'relating'}
CONNECTION = {
    'connect', 'connects', 'connecting', 'connection', 'connections',
    'link', 'links', 'attached', 'coupled', 'associated', 'tied',
    'relation', 'correlated',
}
NEARNESS = {'relevant', 'adjacent', 'similar', 'parallel', 'relative'}
WITH_CONNECTION = STRONG_CONNECTION | RELATING | CONNECTION
TRACKING = {'track', 'tracks', 'tracked', 'tracking', 'tracker', 'trackers'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = LINKING_PARTICLES.get(word, 0.0)

    # Chinese 'and' may be fused with an adjacent word in one token.
    if len(word) > 1 and (word.startswith('和') or word.endswith('和')):
        if word not in {'共和', '共和国', '饱和', '和尚', '和谐'}:
            value = -1.35

    lower = word.lower()
    if lower in TRACKING:
        value = -0.9 if token.startswith(' ') or word[0].isupper() else -0.7
    elif lower == 'alongside':
        value = -0.68
    elif lower == 'closely':
        value = -0.47

    # Recognize the strongest particle even when its UTF-8 bytes split.
    if word == '\ufffd' and previous:
        if prefix.text_prefixes[-1].endswith('跟'):
            value = LINKING_PARTICLES['跟']

    before = previous.strip().lower()
    if lower == 'to':
        if before in STRONG_CONNECTION:
            value = -1.5
        elif before in RELATING:
            value = -1.2
        elif before in CONNECTION:
            value = -0.7
        elif before in NEARNESS:
            value = -0.32
    elif lower == 'of' and before == 'track':
        value = -0.5
    elif lower == 'with' and before in WITH_CONNECTION:
        value = -0.22
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection unit 5963: a "joins-two-things" connective detector.

The unit goes negative on the word that joins two things in a relation and introduces
the second one: a coordinating or comparing connective, such as

  * Chinese "and / with":  跟 (strongest), 與 / 与, 和, 同   (A 与 B = "A with B")
  * Japanese "and / with": と, とは, との;  Korean 와 / 과;  Chinese 比 ("compared with")
  * English "to" right after a relation word: "related to", "connected to", "linked to"
    (and a weaker "with" after such a word: "associated with")
  * the "follow / track" sense: track, tracking, Follow, 追, 找

Each such token gets a fixed negative value, the averages measured on training text;
every other token gets 0. The sign is negative because the unit subtracts a "joins-with"
signal from the residual stream at those positions. The program ignores context apart
from the one previous token, so it has no carry.
"""

READS = ()

# Coordinating / comparing connectives, matched on the whole token (leading space ignored).
CONNECTIVE = {
    "跟": -8.3, "與": -2.8, "与": -2.75, "和": -1.0, "同": -1.2, "比": -0.8,
    "と": -0.85, "とは": -0.9, "」と": -0.9, "との": -1.5, "와": -0.9, "과": -0.9,
}
# Follow / track sense.
FOLLOW = {"track": -0.8, "tracks": -0.9, "tracking": -1.0, "tracked": -0.9,
          "Track": -0.9, "Follow": -0.8, "Following": -0.4, "追": -1.2, "找": -1.1}
# Words after which a bare "to" links two things ("related to").
RELATION = {
    "related": -1.45, "Related": -1.35, "connected": -1.6, "Connected": -1.2,
    "linked": -1.3, "relates": -1.35, "relate": -1.2, "relating": -1.05,
    "associated": -0.9, "attached": -0.65, "coupled": -0.6, "tied": -0.85,
    "connect": -0.9, "connects": -0.9, "connecting": -0.65, "links": -0.55,
    "link": -0.55, "connection": -0.75, "relation": -0.75, "unrelated": -1.2,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if word in CONNECTIVE:
        return carry, CONNECTIVE[word]
    if word.endswith("和") and word != "共和":
        return carry, -1.3
    if word in {"跟着", "跟随", "跟踪"}:
        return carry, -2.0
    if "跟" in word:
        return carry, -7.0
    if word.startswith(("与", "與")):
        return carry, -2.7
    if word in FOLLOW:
        return carry, FOLLOW[word]
    if word == "to" and before in RELATION:
        return carry, RELATION[before]
    if word == "with" and before in RELATION:
        return carry, 0.3 * RELATION[before]
    return carry, 0.0

programs.luna:
"""A lexical proxy for a sparse response to relation markers.

The strongest examples are Chinese 与/和 and Japanese と. English "to"
looks predictive mainly after a word such as "related" or "connected";
ordinary uses of "to" are left alone.
"""
READS = ()

RELATION_WORDS = {
    "与": -2.7,
    "和": -0.95,
    "と": -0.92,
    "กับ": -0.50,
    "比": -0.81,
    " alongside": -0.67,
    " track": -0.90,
}

TO_RELATIONS = {
    "related", "connected", "correlated", "relevant", "relation", "adjacent",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word == " to" and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].strip().lower()
        if previous in TO_RELATIONS:
            return None, -1.15
    return None, RELATION_WORDS.get(word, 0.0)

programs.sol:
"""A lexical mixture, not a general semantic classifier.

Establish/develop/provide/maintain forms give positive pulses. River terms
and several English -iver spelling families give negative pulses. Case,
spacing and inflection change their size. Selected phrases and split
inflections continue the pulse onto the next token, resetting at documents.
Chinese river characters are also recognized after byte-token completion.
Smaller unrelated lexical responses are left near zero.
"""
READS = ()

# Inflections of three word families, not a vocabulary-wide lookup.
FAMILIES = {
    'establish': {'': 4.4, 'es': 4.2, 'ing': 3.95, 'ed': 3.73,
                  'ment': 2.6, 'ments': 1.2},
    'develop': {'': 2.02, 's': 1.61, 'ed': 1.9, 'ing': 2.07,
                'ment': 0.6, 'ments': 1.0, 'er': 0.35, 'ers': 0.35},
    'provid': {'': 0.68, 'e': 0.70, 'es': 0.85, 'ed': 0.44,
               'ing': 0.63, 'er': -0.4, 'ers': -0.2},
}
SPLIT_ENDINGS = {
    'establish': {'ed': 3.3, 'ing': 2.5, 'es': 2.7,
                  'ment': 1.9, 'ments': 1.3},
    'develop': {'ed': 1.4, 'ing': 1.6, 's': 1.9, 'ments': 1.15},
    'provid': {'ed': 0.85, 'ing': 0.7},
}


def lexical(token):
    word = token.strip().lstrip('._-/(')
    low = word.lower()
    for stem, endings in FAMILIES.items():
        if low.startswith(stem) and low[len(stem):] in endings:
            value = endings[low[len(stem):]]
            if stem == 'establish' and not token.startswith(' '):
                value -= 0.3
            if low == 'established' and token.startswith('-'):
                value = 2.9
            return value
    if low in {'maintain', 'maintains', 'maintained', 'maintaining', 'maint'}:
        return 1.04
    if low in {'build', 'builds', 'built', 'building'}:
        return 0.21
    if low in {'acquire', 'acquires', 'acquired', 'acquiring', 'cultivated'}:
        return 0.65
    if low in {'emerging', 'entwick', 'desarroll', 'desarrollo'}:
        return 0.8
    if low == 'river':
        if word == 'River':
            return -8.05 if token.startswith(' ') else -6.65
        return -5.64 if token.startswith(' ') else -4.3
    if low == 'rivers':
        return -5.1
    if low in {'riverside', 'rivera'}:
        return -2.05
    if low in {'driver', 'drivers'}:
        if low == 'drivers':
            return -2.15 if word.islower() else -2.8
        return -3.05 if word.islower() else -3.6
    if low in {'iver', 'ivers'}:
        return -3.6 if word.isupper() else -2.65
    if low in {'iverse', 'iversal'}:
        return -1.8
    if low == 'liver':
        return -1.9
    if low in {'diver', 'divers'}:
        return -1.2
    if low in {'diverse', 'diversity', 'diversified'}:
        return -0.6
    if low in {'univers', 'universe', 'universal', 'universally'}:
        return -1.2
    if low in {'deliver', 'delivering', 'ivered'}:
        return -0.8
    if low in {'delivered', 'delivers', 'delivery', 'deliveries'}:
        return -0.4
    if low in {'lake', 'thames', 'nile', 'рек'}:
        return -1.1 if low in {'lake', 'рек'} else -2.0
    if word == '河':
        return -4.95
    if word in {'黄河', '河流', '河边'}:
        return -3.6
    if word in {'江', '长江'}:
        return -2.0
    if word.startswith('建立'):
        return 2.0
    if '提供' in word:
        return 0.6
    if word == '培养':
        return 1.1
    return -0.002


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word = token.strip().lower()
    value = lexical(token)
    continuation = not token[:1].isspace()
    completed = word
    if continuation and previous in SPLIT_ENDINGS and word in SPLIT_ENDINGS[previous]:
        value = SPLIT_ENDINGS[previous][word]
        completed = previous + word
    elif continuation and previous == 'r' and word in {'iver', 'ivers'}:
        value = -7.0 if token.isupper() else -5.2
        completed = 'r' + word
    elif word == 'of':
        if previous == 'development':
            value = 1.17
        elif previous == 'establishment':
            value = 2.32
        elif previous in {'river', 'rivers'}:
            value = -1.7
    elif previous in {'develop', 'develops', 'developed', 'developing',
                      'establish', 'establishes', 'established', 'establishing'}:
        if word in {'a', 'an'}:
            value = 0.9
        elif word == 'the':
            value = 0.55
        elif word == 'by':
            value = 0.3
    elif previous in {'build', 'builds', 'built', 'building'}:
        if word in {'up', '-up', 'upon'}:
            value = 1.35 if word != 'upon' else 0.95
        elif word == 'on':
            value = 0.73
        elif word in {'a', 'an'}:
            value = 0.28
    # A byte fragment can finish a Chinese river character.
    if '\ufffd' in token and carry is not None and carry[0] == doc:
        character = prefix.text_prefixes[-1][-1:]
        if character in {'河', '江'}:
            value = -4.95 if character == '河' else -2.0
    return (doc, completed), float(value)

programs.haiku:
"""Layer-0 MLP direction 5964 (one down_proj component), as a word-level rule.

For the token just read, it writes a signed value:
- strongly negative on the word "river": capitalised "River" most (a name, e.g. the
  Mississippi River), lower-case "river(s)" a bit less; Chinese 河, 黄河, 河流 likewise;
  weaker for "driver", "liver", "diver", water names like "lake", "ocean", "Thames",
  "Nile", and the Chinese 江;
- positive on verbs of building or sustaining something: "establish" (strongest),
  "develop" and 建立, "maintain", "provide", "acquire"; the noun forms
  "development" and "developer" are weaker.
Every other token gives 0. It reads only the current token, so it needs no carry.
"""

READS = ()

EXACT = {"河": -4.0, "江": -1.9, "黄河": -3.2, "河流": -3.5, "lake": -1.0, "lakes": -0.9,
         "thames": -1.9, "nile": -1.6, "ocean": -0.6, "iver": -2.7, "ivers": -2.3,
         "driver": -2.6, "drivers": -2.3, "liver": -1.8, "diver": -1.1}
BUILD = (("establish", 3.8), ("建立", 2.1), ("develop", 2.0), ("maintain", 1.0),
         ("provid", 0.6), ("acquir", 0.6))


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if word in EXACT:
        return carry, EXACT[word]
    if "river" in word:
        return carry, -7.5 if raw.strip()[:1] == "R" else -5.0
    if word.startswith(("development", "developer")):
        return carry, 0.5
    for stem, value in BUILD:
        if word.startswith(stem):
            return carry, value
    return carry, 0.0

programs.sol:
"""Recognize Vietnamese-looking words and the endings of split syllables.

Vietnamese-specific vowels/tone marks, short Vietnamese grammatical words,
and romanized syllable shapes give negative activations. The response is
weaker for shared East Asian names/rimes. Tool delimiters are independent.
A short memory of distinctive Vietnamese spelling disambiguates shared
syllables. The memory and unfinished word reset at document boundaries.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

GRAMMAR = set('''của bạn có các cũng tôi một để và là với được đã sẽ như
thì từ về đó này nên những phải cho sau còn đến cái gì vì mình chúng
họ nó ông bà anh chị con ở đi ra vào làm thể sự mà'''.split())
# Common unaccented Vietnamese words (e.g. trong=in, khi=when, sinh=birth).
UNACCENTED_PREPOSITIONS = {'trong', 'cho', 'qua', 'sau', 'ra'}
SHORT_VIET_WORDS = set('âm ý rõ lý sĩ ăn hà cô vô cá'.split())
UNACCENTED = set('trong khi gia quy sinh dung nhu tuy xe'.split())
VIET_NAMES = {'viet', 'vietnam', 'vietnamese', 'minh', 'nguyen', '越南'}
ASIAN_NAMES = set('''Nam Ho Chi Thai Thailand Hong Kong Wang Yang Zhang
Chang Chen Wong Song Hung Yuan Beijing Shanghai Han Li Kim Mai China Chinese'''
                  .lower().split())
# Homographs and prefix fragments common in Romance languages.
HOMOGRAPHS = set('''più può già día aún não são têm mão vão tão
côt bât sân mín chá'''.split())
ONSETS = set('''b c ch d g gi gh h k kh l m n ng ngh nh p ph qu r s
 t th tr v x'''.split())
DIPHTHONG_RIMES = {'iang', 'iao', 'uang', 'uai', 'uong', 'ieu', 'uyen'}
SPLIT_RIMES = set('''am an ang anh ao au ay ai ong ung inh uy iang iao
ien ieu ian uan uang uai uong uyen ia'''.split())
EUROPEAN_FUNCTION_WORDS = set('''a an the to of in on at as so be he she we me
my by is it for can no but if or and de du le la les un une en et je tu il
elle se lo con di da per'''.split())
NUCLEI = (r'[aeiouy]|ai|ao|au|ay|eo|eu|ia|ie|ieu|iu|oa|oai|oao|oay|oe|oi|'
          r'ua|uai|uay|ue|ui|uo|uoi|uou|uu|uy|uya|uye|uyu|ye|yeu')
SYLLABLE = re.compile(
    r'^(?:ngh|ng|nh|ch|tr|th|ph|kh|qu|gh|gi|[bcdghklmnrstvx])?'
    r'(?:' + NUCLEI + r')(?:ch|nh|ng|[cmnpt])?$')

@lru_cache(maxsize=16000)
def spelling(text):
    w = text.strip().lower()
    nfd = unicodedata.normalize('NFD', w)
    base = ''.join(c for c in nfd if not unicodedata.combining(c))
    base = base.replace('đ', 'd')
    allowed = all(c in 'abcdefghijklmnopqrstuvwxyzđăâêôơư'
                  or '\u1ea0' <= c <= '\u1ef9'
                  or c in 'áàảãạéèẻẽẹíìỉĩịóòỏõọúùủũụýỳỷỹỵ' for c in w)
    valid = allowed and bool(SYLLABLE.fullmatch(base))
    distinctive = any(c in 'ơưđ' or '\u1ea0' <= c <= '\u1ef9' for c in w)
    return w, base, valid, distinctive


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prior, recent_vietnamese = '', 0
    else:
        _, prior, recent_vietnamese = carry
    token = prefix.token_strings[-1]
    word, base, valid, distinctive = spelling(token)
    spaced = token[:1].isspace()
    if not spaced and word.isalpha():
        whole = prior + word
    else:
        tail = re.search(r'[^\W\d_]+$', token)
        whole = tail[0].lower() if tail else ''
    value = 0.0
    if token == '<tool_response>':
        value = -1.21
    elif token == '</tool_call>':
        value = -0.47
    elif valid and (distinctive or word in GRAMMAR and word != base or
                   spaced and word != base and len(word) >= 3
                   and word not in HOMOGRAPHS and not any(c in word for c in 'éè')):
        if not spaced:
            value = -2.5
        else:
            value = -2.7 if len(word) < 4 else -3.1
        # Shared strengths for function words, demonstratives,
        # plural/additive words, and prepositions.
        if word in GRAMMAR:
            value = -1.8
        if word in {'là', 'này', 'đó', 'đây', 'đấy', 'đâu', 'nào', 'rồi'}:
            value = -1.1
        if word in {'cũng', 'chúng', 'các', 'những'}:
            value = -2.8
        if word in {'của', 'vào', 'với'}:
            value = -2.5
    elif word == 'đ':
        value = -1.7
    elif word in VIET_NAMES:
        value = -3.3 if word in {'minh', 'nguyen'} else -2.2
    elif spaced and word in SHORT_VIET_WORDS:
        value = -2.0
    elif (spaced and word in UNACCENTED_PREPOSITIONS
          and (token.strip().islower() or recent_vietnamese)):
        value = -1.5
    elif spaced and word in UNACCENTED:
        value = -2.2
    elif not spaced and prior and word.isalpha() and spelling(whole)[2]:
        pbase = spelling(prior)[1]
        # The final h completes the Vietnamese palatal nasal spelling nh.
        if word == 'h' and pbase.endswith('n'):
            value = -3.3 if pbase.startswith(('th', 'tr')) else -2.0
        elif word in {'ng', 'nh'}:
            value = -2.0
        elif base in SPLIT_RIMES and (pbase in ONSETS or pbase in {'hu', 'thu', 'vu'}):
            if base.endswith('nh'):
                value = -2.5
            elif base.endswith('ng'):
                value = -1.4
            else:
                value = -0.65
            if pbase in {'tr', 'ph', 'kh', 'qu'}:
                value -= 1.0
    elif word in ASIAN_NAMES and token.strip()[:1].isupper():
        value = -0.6
    if not spaced and value == 0.0:
        if word in DIPHTHONG_RIMES:
            value = -1.1
        elif word in {'anh', 'inh', 'nh'}:
            value = -0.8
        elif word in {'ang', 'ong', 'ung', 'ng', 'uy'}:
            value = -0.2
        elif word in {'ôi', 'ông', 'âu', 'ân', 'ên', 'êu', 'ây'}:
            value = -1.5
    # Ambiguous syllables are stronger shortly after distinctive Vietnamese
    # spelling. Never promote common European function words this way.
    if recent_vietnamese and word.isalpha() and spelling(whole)[2]:
        if whole not in EUROPEAN_FUNCTION_WORDS:
            value = min(value, -1.8)
    if distinctive and valid:
        recent_vietnamese = 8
    elif not token.isspace():
        recent_vietnamese = max(0, recent_vietnamese - 1)
    return (doc, whole[-16:], recent_vietnamese), float(value)

programs.haiku:
"""Candidate 3: personal pronouns, with a table of strengths per pronoun, a bump after
clause-opening words, and a few non-English forms."""
READS = ()
TABLE = {
    "my": 5.5, "me": 2.7, "myself": 2.5, "mine": 1.5, "mi": 1.7, "mon": 1.1, "mein": 2.1,
    "his": 1.6, "her": 1.7, "their": 1.4, "our": 1.3, "your": 1.1, "him": 1.3, "them": 1.3,
    "they": 1.15, "he": 0.9, "she": 0.9, "we": 0.4, "us": 0.9,
    "我的": 3.7, "我": 1.9, "他们": 1.0, "他": 0.6, "她": 0.85,
}
CLAUSE_OPENERS = {"when", "if", "because", "what", "that", "but", "and"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" \t(\"“'")
    if word == "I":
        before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
        return None, 1.6 if before in CLAUSE_OPENERS else 1.0
    if word == "US":
        return None, 0.0
    return None, float(TABLE.get(word.lower(), 0.0))

programs.sol:
"""Mostly a negative lexical signal for play, players and online gaming.

The response extends to 'display' and 'replay', suggesting a word-form bias,
not a reliable game-topic classifier. It also responds positively to common
Python exception names. Small separate offsets describe contractions,
Japanese particles, conversation markers, and formatting. Unrecognized
tokens predict zero. These are lexical responses, not a single topic test.
"""
import re

READS = ()

PLAY_VERBS = {
    'play': -0.27, 'plays': -0.21, 'played': -0.21, 'playing': -0.31,
}
PYTHON_ERRORS = {
    'TypeError': 0.64, 'ImportError': 0.55, 'AttributeError': 0.42,
    'ValueError': 0.40, 'OSError': 0.40, 'NotImplementedError': 0.37,
    'FileNotFoundError': 0.26, 'IndexError': 0.14,
    'AssertionError': 0.09, 'RuntimeError': 0.09,
}
CONTRACTIONS = {
    "'ve": 0.128, "'t": -0.054, "'s": 0.022,
    "'re": 0.034, "'d": 0.034,
}
JAPANESE_PARTICLES = {
    'に': -0.085, 'を': -0.064, 'が': -0.043, 'は': -0.035,
    'も': -0.028, 'で': -0.025, 'の': -0.010, 'と': 0.011,
}
CONVERSATION_MARKERS = {
    "<|endoftext|>": -0.022, "<|im_start|>": 0.012,
    "<|im_end|>": 0.025, "<tool_call>": -0.030,
    "<tool_response>": -0.007, "</tool_response>": -0.098,
    "<think>": 0.057, "</think>": -0.053,
}
CHINESE_GAMING = {
    # Players, games, play.
    '玩家': -0.70, '玩家们': -0.75, '游戏': -0.18, '玩': -0.19,
    # Mobile/online games, gameplay, guides.
    '手游': -1.30, '网游': -0.80, '玩法': -1.05, '攻略': -0.48,
    # Heroes, modes, skills, professions.
    '英雄': -0.40, '模式': -0.28, '技能': -0.14, '职业': -0.12,
    # Board/card games, fishing games, esports, tactics.
    '棋牌': -0.31, '捕鱼': -0.40, '电竞': -0.48, '打法': -0.75,
    # Livestreams, live rooms, streamers, perks.
    '直播': -0.58, '直播间': -0.40, '主播': -0.79, '福利': -0.28,
}


def lexical_value(token):
    word = token.strip().strip('._-/()[]{},:;')
    if token in CONVERSATION_MARKERS:
        return CONVERSATION_MARKERS[token]
    if word in PYTHON_ERRORS:
        return PYTHON_ERRORS[word]
    if word in JAPANESE_PARTICLES:
        return JAPANESE_PARTICLES[word]
    contraction = word.replace('’', "'")
    if contraction in CONTRACTIONS:
        return CONTRACTIONS[contraction]
    lower = word.lower()
    if lower in {'gameplay', 'multiplayer', 'singleplayer', 'playable', 'pvp'}:
        return -0.92
    if re.fullmatch(r'(?:get)?players?(?:id)?', lower):
        return -0.49
    if lower in PLAY_VERBS:
        return PLAY_VERBS[lower]
    if lower.startswith('display'):
        return -0.10
    if lower in {'replay', 'playlist', 'playoff', 'playoffs', 'playbook'}:
        return -0.18
    if lower == 'online':
        return -0.22
    if lower == 'poker':
        return -0.60
    if lower in {'casino', 'casinos'}:
        return -0.29
    if lower in {'slot', 'slots'}:
        return -0.23
    if lower in {'gambling', 'betting', 'jackpot'}:
        return -0.16
    if lower in {'game', 'games'}:
        return 0.05 if word.istitle() else -0.06
    if lower in {'gaming', 'gamer', 'gamers', 'chess', 'minecraft', 'nintendo'}:
        return -0.13
    if lower in {'overwatch', 'fortnite', 'warcraft', 'diablo'}:
        return -0.55
    if word == 'Legends':
        return -0.40
    if lower in {'mode', 'modes', 'strategy'}:
        return -0.14
    if lower == 'competitive':
        return -0.21
    if lower in {'rts', 'rpg', 'melee'}:
        return -0.30
    if lower in {'spieler', 'spielen', 'spiele', 'joueur', 'jouer',
                 'jugar', 'jugador', 'jogador'} or word == 'プレイ':
        return -0.26
    if token.startswith(' ') and lower.startswith(('игрок', 'играть')):
        return -0.58
    if token.startswith(' ') and lower.startswith(('игров', 'игр', 'иг')):
        return -0.20
    if word in CHINESE_GAMING:
        return CHINESE_GAMING[word]
    if '王者荣耀' in word:
        return -1.75
    # Legend/Mir MMORPG advertising: character classes and private servers.
