programs.sol:
"""A layout-sensitive response to source-code comment and logging syntax.

Comment markers following indentation give large negative values, especially
hashes and double slashes. In-line, unindented double slashes can be positive.
Code returns give a smaller positive response; logging calls are negative.
Minor rules cover SQL/HTML comments, TODOs and docstrings.
Other tokens predict zero. State uses the previous token and a 256-character
line tail, treating escaped newlines/tabs as layout and resetting per document.
"""
import math
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, real_line = '', '', False
    else:
        _, previous, line, real_line = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    leading = token[0].isspace() if token else False
    empty_line = not line.strip()
    indent = bool(previous) and previous.isspace() and '\n' not in previous
    indent = indent and '\r' not in previous
    width = math.log2(min(32, len(previous)) + 1) if indent else 0.0
    tab = indent and previous == '\t'
    mixed = indent and '\t' in previous and not tab
    depth = min(4, line.count('\t')) if tab else 0
    fresh_indent = indent and empty_line and real_line
    code_end = bool(re.search(r'[;)}\]]\s*$', previous))
    newline = '\n' in previous
    value = 0.0

    if word == '#' or word in ('#region', '#endregion'):
        value = (0.60 - 0.50 * leading - 0.80 * empty_line
                 - 0.80 * code_end - 0.15 * newline)
        if indent:
            value -= (1.90 + 0.22 * width + 0.50 * fresh_indent
                      + 0.60 * mixed + 0.50 * tab + 0.53 * depth)
        if '\n' in token:
            value += 1.0
    elif word == '//':
        value = (1.70 - 1.10 * leading - 0.70 * empty_line
                 - 0.80 * code_end - 0.25 * newline)
        if indent:
            value -= (1.70 + 0.45 * width + 0.55 * fresh_indent
                      + 0.25 * mixed + 0.65 * tab + 0.80 * depth)
        if '\n' in token:
            value += 0.7
    elif word.startswith('///'):
        value = 0.25 - 0.35 * empty_line - 0.30 * newline
        if indent:
            value -= (0.20 + 0.50 * width + 0.25 * tab
                      + 0.25 * depth + 0.30 * fresh_indent)
    elif word.startswith('//'):
        value = -2.0 if indent else -0.6
    elif re.fullmatch(r'[)\]]+//', word):
        value = 1.8 if not leading else 0.3
    elif word.startswith('/**') and not word.strip('/*!-='):
        value = (1.7 - 0.25 * leading - 0.35 * empty_line
                 - 1.1 * newline + 0.3 * ('\n' in token))
        if indent:
            value -= (0.9 + 1.0 * width - 0.7 * (len(previous) >= 3)
                      - 0.5 * (len(previous) >= 7) + 0.3 * fresh_indent
                      + 0.7 * tab + 0.15 * depth)
    elif word.startswith('/*') and not word.strip('/*!-='):
        value = 1.45 - 2.0 * leading - 0.45 * empty_line - 0.9 * newline
        if indent:
            value -= (1.0 + 0.3 * width + 0.4 * fresh_indent
                      + 1.1 * tab + 0.5 * depth)
    elif word == '*' and leading:
        if indent:
            value = -0.6 if len(previous) == 1 and not tab else -1.4
            value -= 0.4 * (len(previous) >= 4 and not mixed)
            value -= 0.5 * (tab and fresh_indent)
        else:
            value = -0.65 if empty_line else 0.0
        if '\n' in token:
            value *= 0.35
    elif word in ('--', '---'):
        value = (0.4 if word == '--' else 0.0) - 0.45 * leading - 0.3 * empty_line
        if indent:
            value -= 0.4 * width - 0.4 * (len(previous) >= 3)
    elif word == '<!--':
        value = -2.5 if leading else -0.8
    elif word == 'return':
        value = 0.5 if indent or '\t' in token else 0.25 if code_end else 0.05
    elif word == 'continue':
        value = 0.25 if indent else 0.0
    elif word.lower() == 'console':
        value = -0.7 - 0.3 * fresh_indent if indent else -0.1 if empty_line else 0.3
    elif word.lower() == 'logger':
        value = -0.6 if indent else -0.2
    elif word == '.log':
        value = -1.9 if previous.strip().lower() == 'console' else -0.65
    elif word in ('.out', '.println', '.WriteLine', '.debug'):
        value = -0.75
    elif word == 'TODO':
        value = -1.3 if previous.strip() in ('#', '//', '///') else -0.5
    elif '"""' in token or "'''" in token:
        value = -0.4 if indent else -0.1

    line += token
    if '\n' in line or '\\n' in line:
        real_line = line.rfind('\n') > line.rfind('\\n')
    line = line.replace('\\n', '\n').replace('\\t', '\t')
    line = line.rsplit('\n', 1)[-1][-256:]
    return (doc, token, line, real_line), float(value)

