"""Comment openers in code, and logging calls.

Heuristic description of the component (layers.0.mlp.down_proj:5970):
it goes strongly negative on the token that opens a code comment (#, //, /*, ///, *)
when that token starts an indented line, i.e. a comment inside a block of code. It is
weakly negative for a spaced comment marker mid-line (x = 1  # note), negative on
console/log/print method names, and slightly positive on `return`.
Column-0 comment markers and everything else give 0.
"""
import re

READS = ()

MARKERS = {'#', '//', '///', '/*', '/**', '--', '<!--'}   # comment openers, with or without a leading space
JAVADOC = {' *', '*'}                                      # continuation star of a /** block
LOG = {'.log', '.println', '.out', '.debug', 'console', 'Console', '.WriteLine', 'logger', '.Log'}
RETURN = {' return', '\treturn', 'return'}


def line_prefix(strings):
    """Text on the current line before the newest token."""
    text = ''
    for s in reversed(strings[:-1]):
        if '\n' in s:
            return s.split('\n')[-1] + text
        text = s + text
    return text


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    before = line_prefix(prefix.token_strings)
    indented = re.fullmatch(r'\s*(\d+\t)?[ \t]+', before) is not None   # first thing on an indented line
    if tok.lstrip(' ') in MARKERS:
        if indented:
            return None, -3.0
        if tok.startswith(' ') and before.strip() and not re.fullmatch(r'\s*\d+\t?', before):
            return None, -0.65
        return None, 0.0
    if tok in JAVADOC and indented:
        return None, -1.6
    if tok in LOG:
        return None, -0.95
    if tok in RETURN:
        return None, 0.4
    return None, 0.0

