"""Approximate a-versus-t/l contrast in attached Latin-letter fragments.

The preceding token's spelling controls the response: o, r and t strengthen
it; a and w weaken it. An a-initial continuation generally reverses the sign
of a short t/l-initial continuation. Accents and case are normalized, but
all-uppercase tokens, whitespace-led tokens and document starts get zero.
This captures a weak spelling regularity, not every lexical response.
"""
from functools import lru_cache
import unicodedata

READS = ()

@lru_cache(maxsize=8192)
def normalize(token):
    return ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                   if unicodedata.category(c) != 'Mn')


@lru_cache(maxsize=8192)
def strength(previous):
    letters = ''.join(c for c in previous if c.isascii() and c.isalpha())
    return (0.011 + 0.013 * min(len(letters), 8)
            - 0.052 * letters.count('a') + 0.039 * letters.count('o')
            + 0.020 * letters.count('r') + 0.029 * letters.count('t')
            - 0.045 * letters.count('w')
            - 0.027 * (previous[-1:] in 'aeiouy'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    s = normalize(token)
    value = 0.0
    if (carry is not None and carry[0] == doc and token.isalpha()
            and not token.isupper() and s.isascii() and len(s) <= 7
            and carry[1][-1:].isalpha()):
        score = strength(carry[1])
        if s == 'a':
            value = -score
        elif s.startswith(('ar', 'at', 'ah')):
            value = -0.85 * score
        elif s.startswith('a'):
            value = 0.024 - 0.45 * score
        elif s.startswith('t') and len(s) <= 3 and not s.startswith(('th', 'tr')):
            value = 0.042 + score
        elif s.startswith('l') and len(s) <= 3:
            value = score
        elif s.startswith('i') and len(s) <= 3:
            value = -0.031 + 0.65 * score
        elif s in ('ed', 'er', 'es', 'e', 's', 'o', 'os', 'on', 'ons'):
            value = 0.004 + 0.3 * score
    return (doc, s), float(value)

"""A local detector of past/completed word forms and their continuations.

It responds after English -ed endings and common irregular participles.
Coordination, noun heads and code identifiers receive positive responses;
articles/prepositions and sentence endings receive little or none.
Japanese -た/-だ endings also produce a continuation response. History resets
at document boundaries; an initial completed English form has its own response.
The numbers are averages fitted on random training text, not token-id lookups.
