import re

READS = ()
IRREGULAR = set('''given taken written made seen known shown done found built
    born spoken broken grown drawn driven chosen thrown fallen eaten forgotten
    sent bought sold told held kept lost brought caught taught
    frozen worn won begun gone'''.split())
NOT_PAST = set('''red bed need feed speed seed weed reed breed bleed greed
    shed indeed hundred hatred kindred proceed exceed succeed'''.split())
FUNCTION = set('''to by in on with at for as into under over through during
    within without about upon between against among around across toward
    out up off down back away along via after before until since onto inside
    outside together here there herein using according the a an this that
    these those some any all both each every no another other more less most
    only not just one two three several how what when where whether because
    if so than then like per well higher lower'''.split())
PRONOUNS = set('''it he she they we you i him her them us its his their
    my your our'''.split())
COLLECTIONS = set('''list lists set sets map maps array arrays vector vectors
    table tables row rows items options fields arguments parameters records
    files values objects elements entries nodes version versions'''.split())
HEADS = set('''name names type types value data information
    number numbers line lines form forms area areas range ranges time times
    state states results output rate rates approach test tests services'''.split())


def after_past(s):
    w = s.strip().lower()
    if not w:
        return 0.0
    # Without a separating space these are often word/identifier extensions.
    if not s[0].isspace() and w.isascii() and w.isalpha():
        if s[0].isupper() and len(s) > 1:
            return 1.0
        if w == 'ness':
            return 2.0
        if w == 'ly':
            return 1.6
        return 1.0 if w in {'er', 'es', 'ity'} else 0.35
    if w in {'and', 'or'}:
        return 1.44
    if w in {'but', 'nor', 'yet'}:
        return 0.94
    if w in FUNCTION:
        return -0.07
    if w in PRONOUNS or w in {'be', 'been', 'being'}:
        return 0.0
    if w in {'is', 'are', 'was', 'were', 'has', 'have', 'had', 'will', 'would',
             'can', 'could', 'may', 'might', 'must', 'of', 'which'}:
        return 0.60
    if w in COLLECTIONS:
        return 1.15
    if w in HEADS:
        return 0.52
    if w in {'based', 'given', 'stated', 'due'}:
        return 0.91
    if w in {'below', 'above', 'earlier', 'previously', 'recently', 'successfully'}:
        return 0.60
    if s.startswith(','):
        return 0.44
    if s[0] in '.!?;:()[]{}':
        return 0.03
    if s[0] == '_' or (s[0].isascii() and s[0].isupper()):
        return 0.65
    if s[0] == '/':
        return 0.47
    if w.isascii() and w.isalpha():
        return 0.04 if w.endswith('ly') else 0.12
    return 0.17


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    past = previous.lower().endswith('ed') and tail not in NOT_PAST
    value = after_past(s) if past or tail in IRREGULAR else 0.0
    if previous.endswith(('た', 'だ')):
        w = s.strip()
        if w in {'り', 'い', 'ら', 'く', 'かった', 'ければ'}:
            value = 3.2
        elif w in {'こと', 'ことが', 'ことがある', 'ことは', 'ことも',
                   'のは', 'のが', 'とき', 'ところ', 'ところで', 'ような'}:
            # Nominalizers and temporal connectives after a completed form.
            value = 2.3
        elif w and w[0] not in '。、．！？!?,.':
            value = 1.0
        else:
            value = 0.1
    if first:
        if s.lower().endswith('ed') and s.strip().lower() not in NOT_PAST:
            value = 1.5
        elif s.strip().lower() in IRREGULAR:
            value = 2.1
    # Retain just the trailing English word, so split endings are recognized.
    joined = tail + s if s and s[0].isascii() and s[0].isalpha() else s
    match = re.search(r'[a-zA-Z]+$', joined)
    tail = match.group().lower()[-50:] if match else ''
    return (doc, s, tail), float(value)

