"""A lexical detector for English have/get constructions.

Predict a strong negative value for 'have got' and 'have/get to'. Common
past participles have different signs: the activity/experience vocabulary
below is mostly positive, and change/result vocabulary mostly negative.
Perfect auxiliaries amplify these preferences; an intervening adverb
weakens them. These are approximate lexical classes, not universal rules.
Only space-prefixed tokens receive a response; history resets at document
boundaries. The program also recognizes the negative 'all/human/property rights' idiom.
"""

READS = ()
ACTIVITY = set('worked used played felt held searched faced'.split())
EXPERIENCE = set('done seen served lived experienced helped expected offered '
                 'focused watched discussed suffered sold loved kept looked '
                 'applied enjoyed performed fought'.split())
SPEECH = set('said told heard read led spent tried studied described '
             'met followed continued'.split())
CHANGE = set('built developed learned discovered gathered reached chosen '
             'selected emerged formed identified acquired come begun '
             'established gotten'.split())
WEAK_CHANGE = set('found created changed ended started'.split())
HAVE = {'have', 'has', 'having', "'ve", '’ve'}
GET = {'get', 'gets', 'getting', 'got'}
PERFECT_AUXILIARIES = HAVE | {'had'}
SUBJECTS = set('i you he she it we they who'.split())
ADVERBS = set('already recently now long yet just also never ever not only '
              'previously often always really finally since actually even '
              'carefully fully originally newly'.split())
AUX_GAIN = {'have': 1.0, 'has': 1.12, "'ve": 1.08, '’ve': 1.08,
            'having': 0.75, 'had': 0.65, 'been': 0.5,
            "'s": 0.4, '’s': 0.4, "'d": 0.4, '’d': 0.4}
AFTER_HAVE = {'to': -0.7, 'already': -0.85, 'recently': -0.75,
              'long': -0.75, 'yet': -0.75, 'just': -1.3, 'now': -0.2,
              'also': 0.35, 'thus': 0.5, 'greatly': 0.55, 'more': 0.55,
              'it': -0.85, 'access': -0.75, 'the': -0.25}
AFTER_GET = {'to': -0.85, 'it': -0.8, 'the': -0.25, 'a': -0.2,
             'into': -0.85, 'ready': -0.95, 'together': -0.85,
             'here': -0.9, 'started': -1.4}
AFTER_HAD = {'a': 0.3, 'an': 0.3, 'to': -0.08, 'the': 0.09,
             'already': -0.4, 'just': -0.7}
GOT = {"'ve": -4.5, '’ve': -4.5, 'have': -3.3, 'has': -3.6,
       'had': -2.1, 've': -2.1, "'s": -1.8, '’s': -1.8, 'you': -1.4}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev, older = carry[1:] if carry and carry[0] == doc else ('', '')
    across_adverb = prev in ADVERBS and older in PERFECT_AUXILIARIES
    gain = AUX_GAIN.get(prev, 0.06)
    if across_adverb:
        gain = 0.65 * AUX_GAIN[older]
    elif prev in {"'t", '’t'}:
        gain = 0.95 if older in {'haven', 'hasn', 'hadn'} else 0.3
    elif prev in GET:
        gain = 0.75
    elif prev in ADVERBS:
        gain = 0.3
    elif prev in SUBJECTS:
        gain = 0.18
    elif prev in {'was', 'were', 'is', 'are'}:
        gain = 0.1

    response = 0.0
    if word in ACTIVITY:
        response = 1.55
    elif word in EXPERIENCE or word == 'had':
        response = 0.95
    elif word in SPEECH:
        response = 0.55 if gain >= 0.4 else 0.1
    elif word in CHANGE:
        response = -0.8
    elif word in WEAK_CHANGE:
        response = -0.5
    elif word in {'decided', 'arrived'}:
        response = -1.15
    elif word in {'desired', 'hoped'}:
        response = 1.6
    elif word == 'become' and gain >= 0.2:
        response = -1.8
    elif word in {'thought', 'considered', 'known', 'occurred'}:
        response = 0.75 if gain >= 0.4 else 0.15
    value = response * gain
    if word == 'got':
        fallback = -0.9 if prev in SUBJECTS else (
            -2.5 if across_adverb else -1.1 if prev in ADVERBS else -0.45)
        value = GOT.get(prev, fallback)
    elif prev in HAVE:
        value = AFTER_HAVE.get(word, value)
        if word == 'to' and prev == 'has':
            value = -0.6
    elif prev in GET:
        value = AFTER_GET.get(word, value)
        if word == 'to' and prev == 'got':
            value = -1.3
    elif prev == 'had':
        value = AFTER_HAD.get(word, value)
    if word == 'used' and prev == 'be':
        value = -0.16
    if word == 'rights':
        value = -0.9 if prev == 'all' else -0.55 if (
            prev in {'human', 'property', 'legal', 'their', 'your'}) else -0.3
    if not raw.startswith(' '):
        value = 0.0
    return (doc, word, prev), float(value)

