"""Layer 0, MLP down-projection, feature 5985: a word-after-"have" detector.

What it does: it looks at the word just typed, and at the word before it.
- When the previous word is a perfect-tense auxiliary ("have", "has", "had",
  "having", "'ve"), the current word decides the sign:
  * "got" / "gotten" after such an auxiliary ("I've got", "have gotten"): strongly negative.
  * a common past participle of an activity verb ("have played", "has worked",
    "had used", "have lived", "have felt", "have done", "have seen"): positive.
  * "to" ("have to"), "become", "already", "decided", "enough", "come", "long", "it"
    and a few other verbs ("found", "developed", "created", ...): negative.
- Otherwise it is nearly zero, except that "got" is mildly negative anywhere, and the
  same participles get a small positive value.

Why: the component's sign and size depend mostly on which verb follows an auxiliary,
and the verb list is the concept. Values are rounded least-squares fits on training text.
"""

AUX = {"have", "has", "had", "having", "'ve", "’ve"}
GOT = {"got", "gotten"}
PARTICIPLES = {
    "played", "worked", "used", "lived", "felt", "served", "performed", "experienced",
    "had", "done", "seen", "offered", "tried", "helped", "occurred", "attracted",
    "spent", "held", "read", "led",
}
NEG_AFTER_AUX = {
    "to", "already", "become", "decided", "enough", "come", "long", "it", "emerged",
    "access", "found", "selected", "developed", "created", "changed", "concluded", "ended",
    "its",
}
MILD_NEG = {"become", "rights", "emerged", "selected", "chosen", "decided", "developed", "already"}

READS = ()


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    after_aux = prev in AUX
    if cur in GOT:
        value = -4.4 if after_aux else -0.7
    elif after_aux and cur in PARTICIPLES:
        value = 1.0
    elif after_aux and cur in NEG_AFTER_AUX:
        value = -0.6
    elif cur in PARTICIPLES:
        value = 0.1
    elif cur in MILD_NEG:
        value = -0.15
    else:
        value = 0.0
    return carry, float(value)

