"""Detect two-space padding, especially near the beginning of a document.

A token of exactly two ordinary spaces receives a large positive value.
Its response declines with document position and is slightly weaker directly
following a newline. Two nonbreaking spaces also respond; four-column space
indentation receives a small negative value. Longer runs are not split into
pairs. This leaves unrelated lexical activations unmodeled.
"""
from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, follows_newline = 0, False
    else:
        position, follows_newline = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    value = 0.0
    if token and not token.strip(' '):
        width = len(token)
        if width == 2:
            value = 1.00 + 0.66 / sqrt(1.0 + position / 8.0)
            if not follows_newline:
                value += 0.12
            if position == 0:
                value = 1.77
        elif width % 4 == 0:
            value = -0.10
