    'stand': 1.4, 'stands': 1.7, 'stood': 1.7, 'standing': 1.0,
    'upright': 1.65, 'standalone': 1.4, 'standpoint': 1.0,
    'establish': 1.65, 'establishes': 1.5, 'established': 1.4,
    'establishing': 1.7, 'establishment': 1.85, 'establishments': 1.8,
    'independent': 1.45, 'independence': 1.1, 'independently': 1.15,
    'founded': 1.15, 'founding': 0.85,
    'erect': 2.0, 'erected': 1.6, 'erection': 1.0,
