    'create': 0.75, 'creating': 0.74, 'creates': 0.66,
    'created': 0.58, 'creation': 0.53,
    'build': 0.65, 'builds': 0.52, 'built': 0.7,
    'building': 0.37, 'buildings': 0.35,
    'register': 0.85, 'registered': 0.76, 'registers': 0.6,
    'registration': 0.4, 'registry': 0.0,
    'setup': 0.4, 'setting': 0.35, 'settings': 0.2,
    'write': 0.26, 'writing': 0.29, 'written': 0.15,
