    'immediately': 0.97, 'immediate': 0.47, 'instantly': 0.65,
    'instant': 0.29, 'vertical': 0.67, 'vertically': 0.67,
    'perpendicular': 0.89, 'orthogonal': 0.8,
    'arise': 0.52, 'arises': 0.55, 'arose': 0.5,
    'emerge': 0.6, 'emerges': 0.6, 'emerged': 0.57,
    'lập': 3.3, 'đứng': 1.1, 'dựng': 0.76, 'tạo': 0.4,
    'créer': 0.55,
