def lexical_response(text):
    word = text.strip()
    if '立' in word:
        if word == '立':
            return 9.3
        if word in {'立ち', '立て'}:
            return 4.1  # Japanese standing / setting-up inflections.
        if word in {'立法', '立案'}:
            return 3.2  # Establishing laws or cases.
        if word in {'独立', '獨立', '确立', '確立', '树立', '樹立'}:
            return 3.0
        if word in {'建立', '创立', '創立'}:
            return 3.5
        if word in {'私立', '站立'}:
            return 2.5
        if word == '孤立':
            return 0.9
        if word.endswith('立'):
            return 4.3 if len(word) == 2 else 2.2
        if word.endswith('了'):
            return 0.8 * lexical_response(word[:-1])
        return 4.4 / len(word)
    if word == '립':
        return 4.0
    if word == '입':
        return 2.0 if text[:1].isspace() else 0.7
    if word == '建':
        return 1.15
    if word in {'竖', '豎', '竪'}:
        return 2.1
    if word in {'設', '设', '置', '筑', '築', '植', '育'}:
        return 0.7
    if word in {'造', '起', '站', '树', '樹'}:
        return 0.5
    if word in {'创建', '創建', '注册', '註冊'}:
        return 0.9
    if word in {'建设', '建設', '构建', '構建', '创造', '創造'}:
        return 0.6

    clean = word.lstrip('._/#(-:')  # Code identifiers and path segments too.
    lower = clean.lower()
    value = WORDS.get(lower, 0.0)
    if lower in {'stand', 'stands', 'stood', 'upright'}:
        if clean[:1].isupper():
            return 1.0
        if not text[:1].isspace():
            return 0.4  # A word piece, e.g. the end of "understand".
    if lower == 'create' and not text[:1].isspace():
        return 1.15 if word.startswith('_') else 0.95
    if lower == 'register' and clean[:1].isupper():
        return 1.1
    if lower == 'registry' and word == 'registry':
        return 0.6
    if lower.startswith('созд'):
        return 0.55
