def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = lexical_response(text)
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    if text.strip() == '立' and same_doc:
        previous = prefix.text_prefixes[-2][-1:]
