    "establish", "establishes", "established", "establishing", "establishment",
    "establishments", "founded", "founding", "erect", "erected", "stand", "stands",
    "stood", "standing", "standalone", "upright", "vertical", "vertically", "perpendicular",
    "orthogonal", "independent", "independently", "independence", "independ",
}
# Words meaning to create, build, or register something.
CREATE = {
    "create", "creates", "created", "creating", "creation", "build", "builds", "built",
    "building", "register", "registered", "registers", "registration", "mkdir", "makedirs",
}
# Immediately, and words for emerging or arising.
OTHER = {"immediately", "immediate", "instantly", "emerge", "emerges", "emerged", "arise",
         "arises", "arose", "setup"}
# Chinese build/create/establish/register words, besides 立.
ZH_BUILD = {"建", "设", "造", "创", "建立", "设立", "创建", "建造", "建设", "组建", "构建",
            "创造", "重建", "注册", "竖", "垂直", "站", "站在"}


def step(carry, prefix, upstream):
    # Ignore leading spaces, dots, slashes and underscores, as in " create" or ".create".
    tok = prefix.token_strings[-1].strip(" ._/-").lower()
