READS: tuple[str, ...] = ()

MONTHS = set('january february march april may june july august september '
             'october november december'.split())
DAYS = set('monday tuesday wednesday thursday friday saturday sunday'.split())
FUNCTION = set('the a an which each any some many all both every '
               'our their its his her my your and or of to in on at for '
               'with by from as is are be being was were have has had '
               'do does did not no he she they we i who what how where when '
               'can will would should may might could'.split())

# Location complements: IN, ON, AT, and TO/FROM. An article is optional.
LOCATION = {
    'front': (5.3, 0.6, 0.8, 0.6),
    'place': (3.9, 0.0, 0.0, 0.6),
    'middle': (2.8, 1.0, 0.0, 0.6),
    'background': (2.7, 1.0, 0.0, 0.6),
    'foreground': (2.7, 1.0, 0.0, 0.6),
    'midst': (2.2, 0.0, 0.0, 0.0),
    'top': (0.9, 2.6, 2.4, 1.2),
    'bottom': (0.9, 1.5, 2.5, 1.2),
    'right': (1.0, 2.7, 2.1, 1.5),
    'left': (0.4, 2.0, 1.0, 0.8),
    'end': (1.0, 0.3, 1.0, 0.4),
    'back': (1.3, 1.3, 1.5, 0.7),
    'side': (1.0, 1.6, 0.5, 0.5),
    'center': (1.3, 0.3, 1.2, 0.7),
    'ground': (0.9, 1.8, 0.4, 0.4),
    'floor': (0.8, 1.1, 0.3, 0.3),
    'way': (1.5, 1.3, 0.0, 0.3),
}
# Common idiomatic IN-complements, grouped by approximate response strength.
IN_EXPRESSIONS = {
    w: value for value, words in [
        (2.5, 'charge space'),
        (2.0, 'advance turn question need progress favor favour bed between'),
        (1.5, 'order memory use demand motion'),
        (1.1, 'one time view love mind line response total step reality touch'),
        (0.85, 'range accordance conjunction contrast field context form '
               'preparation return relation combination law activity'),
        (0.7, 'detail real public private vain parallel writing practice '
              'depth effect operation control service agreement support'),
        (0.45, 'general particular terms fact addition part history'),
    ] for w in words.split()
}
FOREIGN = {'в': 'in', 'во': 'in', 'на': 'on', 'en': 'in', 'auf': 'on',
           'im': 'in', '在': 'in'}
PREPS = set('in on at to from by of into under over along through for with '
            'around near out after before during'.split())


def response(p, w, article):
    raw_p, p = p, FOREIGN.get(p, p)
    if p not in PREPS:
        return 0.0
    if (raw_p in {'в', 'во'}
            and w.startswith(('верх', 'низ', 'перед', 'нутр'))):
        return 2.4
