        col = {'in': 0, 'on': 1, 'at': 2, 'to': 3, 'from': 3}[p]
        v = LOCATION[w][col]
        if article:
            v *= 0.85
            if w == 'front' and p == 'in':
                v = 2.3
            if w == 'place':
                v = 0.6
    elif p == 'in' and w in IN_EXPRESSIONS:
        v = IN_EXPRESSIONS[w] * (0.65 if article else 1.0)
    elif w in MONTHS or w in DAYS:
        v = 0.8 if p in {'in', 'on'} else 0.05
    elif w in {'dark', 'black', 'white', 'red', 'green', 'blue', 'yellow'}:
        v = 0.95 if p == 'in' else 0.1
    elif w in {'house', 'town', 'city', 'country', 'area', 'region', 'world',
               'park', 'woods', 'forest', 'office', 'street', 'road', 'air', 'water'}:
        v = {'in': 0.6, 'on': 0.4}.get(p, 0.1)
    elif p == 'on' and w in {'demand', 'stage', 'behalf', 'fire', 'duty', 'purpose'}:
        v = 1.4
    elif p == 'at' and w in {'home', 'night', 'room', 'rest', 'risk', 'stake'}:
        v = 1.4
    elif p == 'by' and w in {'default', 'step', 'way', 'side', 'hand', 'means'}:
        v = 0.6
    elif (p, w) in {('of', 'course'), ('along', 'with')}:
        v = 0.75
    elif w in {'one', 'time', 'date', 'day'}:
        v = 0.6 if p in {'in', 'on', 'at', 'to', 'from', 'over', 'by'} else 0.1
    elif w in {'first', 'last', 'same', 'other', 'second', 'third', 'next'}:
        v = {'in': 0.28, 'on': 0.16, 'at': 0.55}.get(p, 0.04)
    elif w in {'this', 'that', 'these', 'those'}:
        v = -0.18 if p in {'in', 'on', 'at', 'to', 'from'} else -0.05
    elif w in FUNCTION:
        v = 0.0
        if p == 'in' and w in {'our', 'all', 'some', 'many', 'both'}:
            v = -0.18
    elif p == 'in' and w == 'english':
        v = 0.72
    elif p in {'in', 'on'} and w in {'der', 'den', 'dem', 'die', 'das'}:
        v = {'den': 0.9, 'dem': 0.5, 'der': 0.15}.get(w, 0.3)
    elif any('\u0400' <= ch <= '\u04ff' for ch in w):
        v = {'in': 0.33, 'on': 0.24}.get(p, 0.05)
    else:
        v = 0.11 if w.isalpha() and p in {'in', 'on', 'at'} else 0.0
    if article and article != 'the':
        v *= 0.4
    return v


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    w = prefix.token_strings[-1].strip().lower().lstrip('-/.')
    v = 0.0
    if history:
        p, article = history[-1], ''
        if p in {'the', 'a', 'an'} and len(history) > 1:
            p, article = history[-2], p
        v = response(p, w, article)
        if w == 'of' and history[-1] == 'front' and 'in' in history[:-1]:
            v = 2.4
        if w == 'time' and history[-1] == 'same' and 'at' in history:
            v = 0.6
    return (doc, (history + (w,))[-4:]), float(v)

