"""layers.0.mlp.down_proj:5988 -- the word that completes an "in / on / at (the) ___" phrase.

The component fires on the noun (or adverb) right after a locative preposition, most
strongly on fixed phrases and place nouns: "in front" (5), "in place" (4), "in charge",
"in space", "in the middle" / "at the bottom" / "on the right" (2-3), "in order" (1.5),
"in August" / "on Monday" (about 1). Other words after "in/on/at" get a small value, and
words after "in/on/at the" a smaller one. "of" after "in front" also fires (2.5).
It is nearly silent on everything else.
"""

READS = ()

PREPOSITIONS = {"in", "on", "at", "under", "into", "в", "на", "auf"}
DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "all", "some", "any",
               "each", "my", "your", "his", "her", "its", "our", "their", "which", "how"}
# place and position nouns: "in front", "in the middle", "at the top", "on the right"
POSITION = {"front": 5.0, "middle": 2.5, "top": 2.0, "bottom": 2.0, "side": 1.5,
            "left": 1.5, "right": 1.5, "back": 1.5, "end": 1.5, "corner": 1.5,
            "background": 2.5, "midst": 2.0, "vicinity": 1.5, "centre": 1.0, "center": 1.0,
            "way": 1.5}
# stock phrases built on one noun: "in place", "in charge", "in order", "in vain"
PHRASE = {"place": 4.0, "charge": 3.0, "space": 2.0, "order": 1.5, "turn": 2.0,
          "progress": 1.8, "vain": 1.0, "custody": 1.2, "accordance": 0.8, "memory": 1.5,
          "time": 1.2, "view": 1.2, "case": 1.0, "question": 1.5, "night": 1.5}
# months and weekdays after "in"/"on": "in August", "on Monday"
TIME = {m: 0.8 for m in ("january", "february", "march", "april", "may", "june", "july",
        "august", "september", "october", "november", "december", "monday", "tuesday",
        "wednesday", "thursday", "friday", "saturday", "sunday")}
WEIGHT = {**POSITION, **PHRASE, **TIME}


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-3:]]
    cur = toks[-1]
    prev = toks[-2] if len(toks) >= 2 else ""
    prev2 = toks[-3] if len(toks) >= 3 else ""
    word = cur.isalpha() and cur not in DETERMINERS
    if prev in PREPOSITIONS and word:
        return carry, WEIGHT.get(cur, 0.2)
    if prev == "the" and prev2 in PREPOSITIONS and word:
        return carry, WEIGHT.get(cur, 0.1)
    if prev == "front" and prev2 == "in" and cur == "of":
