    (-0.8, ('settle', 'settling', 'unsett')),
    (-0.65, ('establish', 'limit', 'unlimit', 'permanent')),
    (-0.82, ('stabil', 'instabil', 'destabil')),
    (-0.46, ('appoint', 'identif', 'designat', 'statut')),
)


def lexical(raw):
    s = raw.strip()
    if '定' in s:
        if s == '定':
            return -6.35
        if s in {'确定', '確定', '安定', '法定', '核定'}:
            return -3.25
        if s in {'不定', '定了'}:
            return -5.6
        return -2.05 if len(s) == 2 else -1.5
    if s == '정':
        return -3.45 if raw[:1].isspace() else -2.5
    if s in {'특정', '결정', '설정', 'định'}:
        return -1.75
    if s in {'決め', '确立'}:
        return -2.2
    if s == '확':
        return -1.3
    if s in {'确保', '確保', '保证', '保證', '确认', '確認', '明确', '安心'}:
        return -1.0
    if s in set('実实實守精静靜寧宁確決訂订'):
        return -1.0
    if s in set('保安立正限稳恒終界'):
        return -0.67

    word = s.lstrip('._/#(-')  # code and hyphenated spellings
    w = word.lower()
    if 'eterm' in w:
        if w.startswith('pre'):
            return -1.95
        if w.endswith('ant'):
            return -0.7
        if w.endswith('ed'):
            return -1.1
        return -1.55 if w.endswith(('ation', 'ing')) else -1.3
    if 'defin' in w:
        if w in WORD_VALUES:
            return WORD_VALUES[w]
        if w.startswith('pre'):
            return -1.55
        if w.startswith('un'):
            return -0.76
        if w.startswith('indefin') or w == 'definitely':
            return -1.25
        return -0.77 if w.endswith(('ition', 'itions')) else -1.1
    if w in WORD_VALUES:
        return WORD_VALUES[w]
    if w == 'init':
        return -0.75 if not raw[:1].isspace() else -0.52
    if w == 'tofixed':
        return -2.15
    if re.match(r'set[A-Z]', word):
        return -0.64
    for value, stems in STEM_GROUPS:
        if w.startswith(stems):
            return value
    # Russian and German fragments of determine, establish, constant, limit.
    if w in {'оп', 'зад'} and raw[:1].isspace():
        return -0.97
    if w.startswith(('редел', 'определ', 'bestimm')):
        return -1.65
    if w.startswith(('установ', 'постоян', 'предел')):
        return -1.0
    if w == 'станов' and not raw[:1].isspace():
        return -0.67
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    value = lexical(raw)
    last = raw[-1:]
    if '\ufffd' in raw:
        # Recover a character whose UTF-8 bytes span multiple tokens.
        last = prefix.text_prefixes[-1][-1:]
        if last == '定':
            value = -7.45
    elif raw == '定':
        # Weaker in given/measured/scheduled/agreed compounds.
        if previous in set('给设確測测鑑'):
            value = -3.8
        elif previous == '仮':
            value = -2.5
        elif previous in set('予内約所指一訂'):
            value = -5.3
        else:
            value = -6.85
    return (doc, last), float(value)

programs.luna:
"""A possessive determiner followed by “own” marks the component's
strongest observed trigger. The rest of the stream is treated as quiet.
"""

READS = ()

POSSESSIVES = {"my", "your", "his", "her", "its", "our", "their"}


def step(carry, prefix, upstream):
    if prefix.token_strings[-1].strip().casefold() == "own":
        if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2].strip().casefold()
            if previous in POSSESSIVES:
                return None, -4.24
    return None, 0.0

programs.sol:
"""Approximate a mostly lexical AND-family response.

Emit negative pulses for the conjunction AND and short spelling neighbors
such as land, band, sand, stand and hand, including word fragments.
Case, boundaries and inflections adjust the pulse; longer derivatives are
weaker. Suppress hand after 'other' and stand after 'under' or 'out'.
Also recognize a few Chinese equivalents and Japanese loanword spellings.
Only the preceding token is remembered, reset at each document boundary.
Small responses on unrelated words are left at zero.
"""
READS = ()

# Short spelling stems, not token IDs: the same rule also handles inflections.
STEMS = {
    'land': 3.7,
    'band': 4.3,
    'sand': 4.5,
    'stand': 4.0,
    'hand': 2.3,
    'brand': 2.1,
    'grand': 2.2,
    'strand': 2.3,
    'rand': 5.5,
    'mand': 3.8,
    'wand': 3.7,
    'cand': 4.5,
    'pand': 3.8,
    'vand': 4.8,
    'tand': 3.3,
}
# Chinese equivalents of the same stems, plus Japanese loanword spellings.
RELATED_WORDS = {
    '手': -0.7,       # hand
    '土地': -2.8,     # land
    '陆': -2.0,       # land
    '沙': -1.0,       # sand
    '砂': -1.7,       # sand
    '立': -0.75,      # stand
    '品牌': -1.4,     # brand
    '而且': -1.0,     # and / moreover
    '且': -0.95,      # and / moreover
    'ランド': -3.0,   # land
    'バンド': -3.7,   # band
}
INFLECTIONS = {'': 1.0, 's': 0.85, 'ed': 0.7, 'ing': 0.75, 'y': 0.7}


def lexical_value(token, previous):
    word = token.strip(' \t\n\r.,;:_-/("\'—')
    lower = word.lower()
    spaced = token[:1].isspace()
    capital = word[:1].isupper()
    inside_word = token == word and previous[-1:].isalnum()
    if lower == 'and':
        if token == ' and':
            ending = previous[-1:]
            if ending == ',':
                return -1.22
            if ending and (ending.isdigit() or ending in ')]}'):
                return -1.27
            return -1.38
        if token.startswith(('—', '–')):
            return -2.0
        if token[:1] in '-_.':
            return -3.2
        if inside_word:
            if word == 'And':
                return -3.3
            return -5.1 if word == 'AND' else -4.8
        if capital:
            return -2.1 if spaced else -2.3
        return -2.0 if previous[-1:].isspace() else -2.7
    if word in RELATED_WORDS:
        return RELATED_WORDS[word]
    if lower == 'stood':
        return -3.1 if spaced else -0.5
    if lower == 'анд':
        return -4.4
    if any(s in lower for s in ('änd', 'ând', 'ánd')):
        return -1.9
    if token.endswith('&&'):
        return -0.65
    if token == '>&':
        return -0.85
    if 'and' not in lower:
        return 0.0
    for stem, strength in STEMS.items():
        if not lower.startswith(stem):
            continue
        suffix = lower[len(stem):]
        if stem == 'hand' and previous.lower().strip() == 'other':
            return 0.0
        if (stem == 'stand' and inside_word
                and previous.lower().endswith(('under', 'out'))):
            return -0.9
        if suffix.startswith(('le', 'ling', 'ard')):
            return 0.0
        if stem == 'cand' and suffix:
            return -2.1 if suffix.startswith(('y', 'idate')) else -1.0
        if stem == 'rand' and suffix.startswith('om'):
            return -1.2
        if suffix in INFLECTIONS:
            strength *= INFLECTIONS[suffix]
            strength += capital * (0.0 if stem in ('hand', 'rand') else 0.7)
            strength += inside_word * (1.0 if stem in ('hand', 'rand') else 0.1)
            return -strength
        return -0.4 * strength * 0.75 ** max(0, len(suffix) - 3)
    if lower.startswith('and'):
        suffix = lower[3:]
        if suffix.startswith('roid'):
            return 0.0
        strength = 5.3 if suffix == 's' else 3.2
        if suffix in ('o', 'on', 'um', 'an', 'le', 'id'):
            strength = 0.85 if suffix == 'o' else 1.6
        strength *= 0.5 ** max(0, len(suffix) - 2)
        return -strength * (0.55 if spaced or capital else 1.0)
    if lower.endswith('and') and len(lower) <= 5 and inside_word:
        return -4.4
    if lower in ('island', 'islands', 'inland'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), float(lexical_value(token, previous))

programs.luna:
"""Use the text just after a standalone English “in” as a weak cue.

Number/date-like tokens and “the” get a negative estimate; other next
words get a positive one. The outputs are deliberately small: this cue
misses most of the component's context-dependent variation.
"""
READS = ()

MONTHS = {
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
}
DIRECTIONS = {"north", "south", "east", "west"}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[1] != doc:
        tail = ""
    else:
        tail = carry[0]
    lower = tail.lower()
    # Current position starts the phrase after a standalone 'in'.
    active = lower.endswith(" in") or lower.endswith(" in ")
    value = 0.0
    if active:
        # Dates, numbers and labels following 'in' tend to be negative.
        clean = token.strip()
        if not clean or clean[0].isdigit():
            value = -1.0
        elif clean.lower() == "the":
            value = -0.8
        elif (
            clean.lower() in MONTHS
            or clean.lower() in DIRECTIONS
            or clean.lower() == "time"
        ):
            value = -0.65
        else:
            value = 0.65
    # A continuation subtoken in a number/date commonly stays active.
    elif (
        tail
        and tail[-1:].isdigit()
        and token.strip()
        and token.strip()[0].isdigit()
    ):
        value = -0.55
    new_tail = (tail + token)[-48:]
    # A weak estimate avoids overpredicting this rare feature.
    return (new_tail, doc), float(value * 0.15)

programs.haiku:
"""Enumeration-comma detector for layer 0's MLP output.

The component is strongly active on the Chinese/Japanese enumeration comma 、 (as in
"甲、乙、丙"), and more weakly on other CJK punctuation that separates or closes items:
：；》】！？・」』” and the kana particle や. Its size on 、 depends on the character just
before it: after a Chinese character it is large, after a kana character moderate, after
a digit or a Chinese numeral (list numbering such as "1、" or "一、") small. After a
Chinese character it is smaller in Japanese text, which the program detects as kana
appearing earlier in the same document. Everything else is about zero.
"""

READS = ()

HAN = (0x4E00, 0x9FFF)
HIRAGANA = (0x3040, 0x309F)
KATAKANA = (0x30A0, 0x30FF)
NUMERALS = set("一二三四五六七八九十")
# typical activations of other CJK punctuation and particles, in the same units
OTHER_MARKS = {
    "や": 1.5, "》": 1.2, "：": 0.6, "・": 0.9, "】": 0.8, "』": 0.8, "！": 0.5,
    "？": 0.5, "；": 0.5, "」": 0.6, "”": 0.2,
}


def _in(ch, lo_hi):
    return lo_hi[0] <= ord(ch) <= lo_hi[1]


def _is_kana(ch):
    return _in(ch, HIRAGANA) or _in(ch, KATAKANA)


def _comma_size(prev, japanese):
    """Typical activation of 、 given the character just before it."""
    if prev == "":
        return 4.0
    if _in(prev, HAN):
        return 3.8 if japanese else 5.9
    if _is_kana(prev):
        return 3.0
    if prev.isdigit() or prev in NUMERALS:
        return 1.1
    return 4.0


def step(carry, prefix, upstream):
    # carry: whether kana has appeared earlier in the current document
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    japanese = carry if same_doc else False
    tok = prefix.token_strings[-1]
    if "、" in tok:
        prev = prefix.token_strings[-2][-1:] if same_doc else ""
        value = _comma_size(prev, japanese)
    else:
        value = OTHER_MARKS.get(tok, 0.0)
    japanese = japanese or any(_is_kana(c) for c in tok)
    return japanese, float(value)

programs.sol:
"""Approximate a lexical time/frequency and restriction detector.

Never/ever respond most strongly, then always and permanence/rarity words.
Negation and restrictive quantifiers respond more weakly. The preceding
word changes auxiliary negation and cancels restriction in not-only/just;
perfect and future auxiliaries also modulate the large temporal responses.
Case, spacing, translations and ver/server spillover are handled explicitly.
All strengths are rounded training estimates, not a complete lexical model.
"""
READS = ()

FREQUENCY = {
    'rarely': 3.55, 'seldom': 2.8, 'permanently': 3.55,
    'permanent': 2.5, 'forever': 2.3, 'almost': 1.4,
    'whenever': 1.35, 'constantly': 1.2,
    'sometimes': 1.0, 'every': 1.0,
    'often': 0.66, 'once': 0.7, 'usually': 0.55,
    'occasionally': 1.05, 'regularly': 0.48, 'frequently': 0.6,
    'rare': 0.97, 'still': 0.22,
    'invariably': 1.5, 'indefinitely': 1.0, 'lifelong': 1.15,
    'commonly': 0.4, 'generally': 0.45, 'soon': 0.6,
    'finally': 0.65, 'eventually': 0.8, 'nearly': 0.8,
}
RESTRICTION = {
    'only': 0.85, 'just': 0.8, 'simply': 0.8, 'either': 0.76,
    'neither': 0.8, 'exactly': 0.7, 'actually': 0.6,
    'former': 0.8, 'everyone': 0.75, 'everything': 0.37,
    'whatever': 1.15, 'whichever': 1.2, 'wherever': 1.3,
    'everywhere': 1.15, 'everybody': 0.8, 'anywhere': 0.7,
    'entirely': 0.85, 'completely': 0.68, 'absolutely': 0.77,
}
# Common lexical equivalents of never, always, and negation.
TRANSLATIONS = {
    'nunca': 4.4, 'jamais': 3.6, 'никогда': 3.6,
    'siempre': 2.6, 'всегда': 2.5, 'toujours': 2.45, 'sempre': 2.2,
    'не': 0.68, 'nie': 0.5, 'nicht': 0.37, 'mai': 0.9,
    'immer': 0.9, 'überhaupt': 1.3, 'вообще': 1.5,
}

# East Asian permanence, frequency, restriction, and negation words/pieces.
# 永 means eternal; 永远/永遠 forever; 永不 never; 永久 permanent.
EAST_ASIAN = {
    '永': 6.5, '永远': 6.5, '永远不会': 5.8, '永不': 7.3,
    '永遠': 4.6, '永久': 3.3, '始终': 2.8, '永恒': 2.8,
    '恒': 1.3, 'いつも': 1.3, '总是': 1.3, '几乎': 1.3,
    '常': 1.0, '久': 1.0, '长期': 1.0, '每': 0.7, 'のみ': 0.7,
    '不会': 0.6, '不': 0.27,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1].strip().lower() if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip(' \t\r\n_-./')
    w = word.lower()
    value = FREQUENCY.get(w, RESTRICTION.get(w, 0.0))

    if w == 'never':
        value = 6.3 if word.isupper() else 7.4
        if word == 'Never':
            value = 7.95
    elif w == 'ever':
        value = 6.9 if raw.startswith(' ') else 2.8
        if word == 'Ever':
            value = 5.2
        elif word.isupper():
            value = 6.0
        elif raw.startswith('-'):
            value = 4.9
    elif w == 'always':
        value = 3.9 if raw.startswith(' ') or word == 'Always' else 3.4
    elif word in EAST_ASIAN:
        value = EAST_ASIAN[word]
    elif w == 'not':
        value = 0.85
        if prev in {'do', 'does', 'did'}:
            value = -0.25
        elif prev in {'is', 'are', 'was', 'were', 'will', 'would',
                       'may', 'can', 'could', 'should'}:
            value = 0.1
        elif prev in {'am', 'have', 'has', 'had', "'s", '’s',
                       "'m", '’m', "'re", '’re', 'shall', 'must'}:
            value = 0.42
        elif prev in {'if', 'or'}:
            value = 0.48
        elif prev in {'might', 'need'}:
            value = 0.26
    elif w in TRANSLATIONS and raw.startswith(' '):
        value = TRANSLATIONS[w]
    elif w in {'ver', 'vers', 'verz', 'server', 'servers'}:
        # A small orthographic spillover, not a claim about these words' meaning.
        value = 0.85 if raw.startswith(' ') else 1.25

    if w in {'only', 'just'} and prev in {'not', "'t", '’t'}:
        value = 0.05
    if w == 'just' and prev in {'is', 'are', 'was', 'were', 'be'}:
        value = 0.6
    if w == 'matter' and prev == 'no':
        value = 1.4
    # Perfect aspect and possibility weaken the large frequency responses;
    # a future auxiliary strengthens them. Only the preceding word is used.
    if w in {'never', 'ever', 'always'} and raw.startswith(' '):
        if prev in {'have', 'has', 'had', "'ve", '’ve'}:
            value -= 0.9 if w == 'never' else 0.4
            if prev == 'had':
                value += 0.3
        elif prev in {'will', 'shall', "'ll", '’ll'}:
            value += 0.4
        elif prev in {'can', 'could'} and w != 'ever':
            value -= 1.0 if w == 'never' else 0.4

    if w in {'no', 'all', 'both', 'very', 'true', 'also', 'each',
              'without', "'t", '’t'}:
        value = -0.12
    return (doc, raw), float(value)

