"""Approximate a local second-person predicate response.

Futures, conditionals and contractions after 'you' are strongly negative;
thought and preference verbs are often positive, especially 'do you think'.
'We' and 'they' give weaker responses. Capitalization and apostrophe style
adjust the strengths. Letters continuing an 'ou' spelling fragment also
receive negative values. Row/document starts have separate values for the
chat-start marker and 'you'. All other positions get zero. Keep two tokens
of context, resetting them at document boundaries.
"""

READS = ()
CONTRACTIONS = {"'ll": -2.74, "'d": -2.31, "'re": -1.34, "'ve": -1.00}


def predicate(word, before):
    if word in CONTRACTIONS:
        return CONTRACTIONS[word]
    if word == 'will':
        return -1.98
    if word == 'would':
        return -1.65
    if word in {'may', 'might', 'shall'}:
        return -0.86
    if word in {'are', 'were', 'be', 'do', 'did', 'had'}:
        return -0.65
    if word in {'should', 'could'}:
        return -0.23
    if word in {'can', 'have'}:
        return 0.05
    if word == 'must':
        return 0.40
    if word == 'think':
        return 2.35 if before == 'do' else 1.25
    if word == 'mean':
        return 0.78 if before == 'do' else -0.15
    if word in {'like', 'agree', 'wish', 'say'}:
        return 1.00
