"""A small lexical approximation, with a strong legal-citation response.

Section marks following C.F.R. are strongest; those following U.S.C. are
weaker. A small set of scientific and literary names and other fixed expressions
have explicit levels. Scientific names usually peak more strongly when
the genus is abbreviated; some have negative rather than positive levels.
The quiet background is more negative for long, space-prefixed words,
capitalized words, and comparison words; function words are nearer zero.
Only the last 80 characters are kept; state resets at document boundaries.
"""
import re

READS = ()

FUNCTION_WORDS = set('''
a an the and or but nor yet so in on at by for from to of with as into
onto upon over under between among through after before around along
i me my mine we us our ours you your yours he him his she her hers
it its they them their theirs who whom whose what which am is are
was were be been being have has had do does did will would can could
shall should may might must this that these those how why when where
whether
'''.split())
COMPARISONS = set('''
more most less least much many few fewer little other another same
different similar identical than such
'''.split())
# Genus, species, abbreviated-genus and full-genus levels.
ORGANISMS = (
    ('Helicobacter', 'pylori', 0.545, 0.157),
    ('Escherichia', 'coli', 0.373, 0.334),
    ('Staphylococcus', 'aureus', 0.362, 0.138),
    ('Saccharomyces', 'cerevisiae', 0.313, 0.162),
    ('Listeria', 'monocytogenes', 0.300, 0.150),
    ('Caenorhabditis', 'elegans', 0.304, 0.093),
    ('Candida', 'albicans', 0.251, 0.134),
    ('Mycobacterium', 'tuberculosis', 0.280, 0.075),
    ('Drosophila', 'melanogaster', 0.327, 0.093),
    ('Clostridium', 'difficile', None, 0.384),
    ('Pseudomonas', 'aeruginosa', 0.196, 0.145),
    ('Candida', 'glabrata', -0.145, None),
    ('Bacillus', 'subtilis', -0.090, -0.052),
    ('Arabidopsis', 'thaliana', -0.047, -0.020),
)

# Familiar literary names normally written with initials.
WRITERS = (
    ('J.R.R.', 'Tolkien'), ('J.K.', 'Rowling'), ('H.G.', 'Wells'),
    ('C.S.', 'Lewis'), ('T.S.', 'Eli'), ('W.W.', 'Norton'),
    ('W.', 'Somerset'),
)


def phrase_peak(tail, s):
    """Recognizable, locally completed abbreviated names and fixed phrases."""
    q = s.strip()
    compact = tail.replace(' ', '')
    if s.startswith(' '):
        for initials, name in WRITERS:
            if compact.endswith(initials) and q == name:
                return 0.34
        if tail.endswith('St.') and q in {'Louis', 'Lawrence'}:
            return 0.26
        if tail.endswith('st.') and q == 'louis':
            return 0.44
        if tail.endswith('U.S.'):
            if q == 'dollar':
                return 0.31
            if q in {'Army', 'Navy', 'Treasury', 'Department', 'Government'}:
                return 0.20
        if tail.endswith('Pat.') and q in {'Nos', 'No'}:
            return 0.28 if q == 'Nos' else 0.11
    if s == 'Sea' and tail.endswith('Carib'):
        return 0.30
    return None


def background(s):
    q = s.strip()
    if not q or q.isdigit():
        return -0.002
    if q == '<|im_start|>':
        return -0.002
    if q == '<|im_end|>':
        return 0.020
    if q.startswith('<|') and q.endswith('|>'):
        return 0.009
    if not q.isalpha():
        return -0.010 if any(c.isalpha() for c in q) else 0.0
    if not q.isascii():
        return -0.004
    leading = s[0].isspace()
    value = -0.007 - 0.002 * (min(12, len(q)) - 4)
    if leading:
        value -= 0.012 + 0.0007 * (min(12, len(q)) - 4)
    if q.istitle():
        value -= 0.008
    if q.isupper() and len(q) > 1:
        value -= 0.014
    if len(q) == 1:
        value += 0.004
    if q.lower() in FUNCTION_WORDS:
        value += 0.010 if leading else 0.006
    if q.lower() in COMPARISONS:
        value -= 0.007
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    q = s.strip()
    peak = phrase_peak(tail, s)
    value = background(s) if peak is None else peak
    if '§' in s:
        value = 0.10
        if s.startswith(' '):
            if tail.endswith('C.F.R.'):
                value = 0.66 if q == '§' else 0.59
            elif tail.endswith('A.R.S.'):
                value = 0.60
            elif re.search(r'U\.S\.C\.(?:A\.)?$', tail):
                value = 0.25 if q == '§' else 0.35
            elif re.search(r'[A-Z]\.(?:[A-Z]\.)+$', tail):
                value = 0.25
            elif re.search(r'[A-Za-z]{2,}\.$', tail):
                value = 0.16
    elif s.startswith(' '):
        for genus, species, abbreviated, full in ORGANISMS:
            if len(q) >= 2 and species.startswith(q):
                if tail.endswith(genus) and full is not None:
                    value = full
                    break
                if abbreviated is not None and re.search(
                    r'\b' + genus[0] + r'\.$', tail
                ):
                    value = abbreviated
                    break
    return (doc, (tail + s)[-80:]), float(value)

