"""Detect reference and specificity, mostly as negative lexical pulses.

Strong cues are 'its', 'where', 'particular', Chinese 其/其中, and
Japanese その/それ. A preposition makes 'which' negative; 'in particular'
is stronger than adjectival 'particular'. Recognize a small set of foreign
possessive and locative expressions too. Unrecognized tokens are zero.
'Their' is weakly negative and 'they' weakly positive. Remember only the
previous token's word within a document. Byte fragments are
checked for a completed Unicode character, allowing split 其中 as well.
"""
READS = ()

PREPOSITIONS = frozenset(
    'in of to for at on from by with through upon under over within during '
    'after around among between without into about against'.split())
ANAPHORIC_REFERENCE = frozenset(
    'thereof therein wherein их них его её deren dessen'.split())

# Possession, containment, demonstratives: Chinese and Japanese forms.
REFERENCE = {
    '其': -3.72, '其中': -7.45, '其实': -1.85, '其實': -1.53,
    '中': -0.50, '之': -1.03, '之中': -1.53, '之一': -1.28,
    '从中': -1.8, '该': -1.0, '該': -1.0,
    '将其': -1.14, '使其': -1.11,
    'その': -3.36, 'それ': -1.92, 'それが': -1.9, 'それに': -2.1,
    'それを': -1.58, 'それは': -0.97, 'そこ': -2.64,
    'そんな': -1.37, 'そう': -1.09, 'これ': -0.78,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    separate = token[:1].isspace() or token[:1].isupper()
    fragment = '\ufffd' in token
    if fragment:
        last = prefix.text_prefixes[-1][-1:]
        if last and last != '\ufffd':
            word = last
    value = REFERENCE.get(word, 0.0)
    if word.startswith('其中'):
        value = -7.45 if word == '其中' else -4.4
        if word == '其中包括':
            value = -2.42
    elif word == '其' and fragment:
        value = -4.9
    elif word == '中' and previous == '其':
        value = -7.45
    if word == 'where':
        value = -0.75 if token.startswith(' ') else -0.92
    elif word == 'its':
        value = -1.05 if separate else -0.19
    elif separate:
        if word == 'which' and previous in PREPOSITIONS:
            value = -0.65
            if previous == 'in':
                value = -1.15
            elif previous in {'of', 'to', 'after', 'around'}:
                value = -0.50
            elif previous in {'through', 'within', 'during', 'among'}:
                value = -0.98
        elif word == 'particular':
            value = -2.5 if previous == 'in' else -1.45
        elif word in {'particularly', 'specifically'}:
            value = -0.95
        elif word == 'specific':
            value = -0.27
        elif word in ANAPHORIC_REFERENCE:
            value = -1.15
        elif word in {'où', 'donde', 'dont'}:
            value = -0.63
        elif word == 'где':
            value = -1.2
        elif word == 'their':
            value = -0.12
        elif word == 'they':
            value = 0.17
    return (doc, word), float(value)

