"""Recognize L as a letter, across several writing systems.

Single-letter pieces receive negative values, strongest for lambda inside
Greek prose. The last sixteen decoded characters distinguish prose from
math symbols. Whitespace, case, and repeated letters adjust the magnitude.
Byte-level tokenization also gives two UTF-8 continuation bytes a positive
response; completing an Indic L is an exception. Short L-bearing syllables
and three conversation-control tags have additional small lexical offsets.
Everything else is zero. This approximates responses, not downstream purpose.
"""
import unicodedata

READS = ()

INDIC_L = frozenset('लळলਲલଲலలಲല')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, start = '', prefix.position
    else:
        previous, start = carry[1:]
    token = prefix.token_strings[-1]
    spaced = token[:1].isspace()
    word = unicodedata.normalize('NFKC', token).strip()
    word = word.strip('._-/\\$[({\'"')
    value = 0.0

    if '�' in token:
        # Decoding the prefix resolves characters split across token boundaries.
        decoded = prefix.text_prefixes[-1]
        if start:
            decoded = decoded[len(prefix.text_prefixes[start - 1]):]
        decoded = decoded or '�'
        end = decoded[-1:]
        final_byte = end.encode('utf-8')[-1]
        if end in INDIC_L:
            value = -1.35
        elif end in 'λΛ':
            value = -0.85
        elif final_byte == 0xB2:
            value = 0.40 if end in ('′', '″') else 0.82
        elif final_byte == 0xB3:
            name = unicodedata.name(end, '')
            if 'REGIONAL INDICATOR' in name:
                value = 1.28
            elif end.isdigit():
                value = 0.70
            elif 'CJK' in name or 'HIRAGANA' in name or 'KATAKANA' in name:
                value = 0.30
            else:
                value = 0.45
    elif word in 'λΛ' and word:
        greek_word = previous and 'GREEK' in unicodedata.name(previous[-1], '')
        # A space-attached lambda in Greek prose is stronger than a math symbol.
        greek_prose = sum('GREEK' in unicodedata.name(c, '')
                          for c in previous) >= 4
        if spaced:
            value = -0.90 if greek_prose else -0.32
        elif greek_word:
            value = -1.55 if greek_prose else -0.75
        else:
            value = -0.30
        if greek_word and greek_prose and not spaced:
            if previous[-1] in 'οΟ':
                value = -1.90
            elif previous[-1] in 'λΛ':
                value = -1.10
            elif word == 'Λ':
                value = -1.80
    elif word in ('l', 'L', 'ł', 'Ł'):
        if word.isupper():
            value = -0.04 if spaced else -0.09
        else:
            value = -0.15 if spaced or token.startswith('-') else -0.30
        if word == 'L' and not spaced and previous[-1:].isupper():
            value = -0.24
        if previous.lower().endswith('l') and not spaced:
            value *= 0.25
    elif word in ('л', 'Л'):
        value = -0.38 if word.isupper() else -0.27
        if previous.lower().endswith('л') and not spaced:
            value = 0.0
    elif word == 'ل':
        value = -0.50 if spaced else -0.66
    elif word in ('ال', 'لا'):
        value = -0.25
    elif word == 'ל':
        value = -0.50
    elif word in INDIC_L or word in ('ล', 'ລ', 'ლ'):
        value = -1.10
    elif word.lower() == 'lambda':
        value = -0.23
    elif word in ('al', 'el', 'il', 'ol') and not spaced:
        value = -0.08
    elif word == 'Al':
        value = -0.21
    elif word == 'le' and not spaced:
        value = 0.14 if previous.lower().endswith('l') else 0.035
    elif token in ('<tool_response>', '<think>', '</think>'):
        value = 0.15

    end = (decoded[-16:] if '�' in token
           else (previous + token)[-16:])
