        value = damage(word)
        if word == 'return':
            value = -0.95 if token.startswith('\t') else -0.8
            if token.strip() != 'return':
                value = -0.63
        elif word in {'returns', 'returned', 'returning', 'continue'}:
            value = -0.23 if word == 'continue' else -0.5
    if previous in BREAK_FORMS:
        if not token[:1].isspace() and word in SUFFIXES:
            value = SUFFIXES[word]
            if word == 's' and previous not in {'break', 'breaking'}:
                value = -1.7
        elif word.startswith(';'):
            value = -0.7
        elif word == 'of':
            value = -4.2 if previous in {'break', 'breaking'} else -1.9
        elif word == 'the':
            value = -1.5 if previous == 'broken' else -2.7
        elif word in {'a', 'an', 'it', 'from', 'up', 'down', 'out'}:
            value = -1.3
        elif word in {'in', 'into', 'through', 'away', 'his', 'my'}:
            value = -0.7
    elif damage(previous) and word == 'of':
        value = 0.9 * damage(previous)
    return (doc, word), float(value)

