"""Word detector for "break": component layers.0.mlp.down_proj:6008.

This component is a strong negative detector for the word "break" in its verb forms
(break, breaks, breaking, broke, broken, with a leading space or underscore), and for the
Chinese words 破 / 突破 / 破坏 (break, break through, break apart). It reads the current token
alone: the value depends only on which word the token spells, not on the context.

It is weaker on other words that start with "break" (breakthrough, breakdown, breakpoint,
breakfast: about -2.5), and mildly negative on "return" and its forms (about -0.8). On
every other token it is near zero.

Predicted activation: the value below, per token; 0 elsewhere.
"""

READS = ()

BREAK_VERBS = {"break", "breaks", "breaking", "broke", "broken"}
CJK_BREAK = {"破", "突破", "破坏"}
RETURN_WORDS = {"return", "returns", "returned", "returning"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.lower().lstrip("_")
    if word in BREAK_VERBS or token in CJK_BREAK:
        value = -6.5
    elif word.startswith("break"):
        value = -2.5
    elif word in RETURN_WORDS:
        value = -0.8
    else:
        value = 0.0
    return carry, value

