"""A sparse activity-word approximation, strongest on Chinese work and daily life.

Related production, education, use, and business words have weaker negative
responses. Grammatical wrappers and a few transparent compound types alter
that response. English daily-life and learning phrases depend on their
immediately preceding word. These classes summarize large training responses;
unmatched tokens are zero, leaving smaller diffuse responses unexplained.
"""

READS = ()

PRODUCTION = {'生产', '生產', '建设', '建設'}
BUSINESS = {'经营', '經營', '运营', '運營', '写作', '寫作'}
EDUCATION = {'学习', '學習', '教学', '教學', '办公', '辦公'}
OPERATIONS = {'使用', '操作', '运维', '運維', '运行', '運行', '制作', '製作'}
CHANGE = {'发展', '發展', '改革', '生存', '生长', '生長'}
ACTIONS = {
    '销售', '銷售', '旅行', '治理', '科研', '居住', '上班', '种植', '種植',
    '养殖', '養殖', '交易', '实习', '實習', '治疗', '治療', '阅读', '閱讀',
}
ENGLISH_ROUTINES = {
    'operate': -0.8, 'operating': -0.8, 'operates': -0.65,
    'teaching': -0.6, 'shopping': -0.5, 'operation': -0.35,
    'production': -0.2, 'writing': -0.2, 'living': -0.22,
    'growth': -0.27, 'lifestyle': -0.55,
}


def chinese_activity(word):
    bare = word.strip('的和')
    if bare == '生活':
        return -3.35
    if bare == '工作':
        return -2.85 if word == bare else -2.6
    if word in {'生活中', '工作中', '生活在'}:
        return {'生活中': -1.9, '工作中': -1.2, '生活在': -1.25}[word]
    if word.endswith('工作'):
        return -2.6
    if word.startswith('工作') and word[2:] in {'经验', '岗位', '任务'}:
        return -1.1
    if bare in PRODUCTION:
        return -1.85 if word == bare else -1.5
    if bare in BUSINESS:
        return -1.35
    if bare in EDUCATION:
        return -1.1 if word == bare else -1.3
    if bare in OPERATIONS:
        return -0.85
    if bare in CHANGE:
        return -1.0 if word == bare else -1.35
    if bare in ACTIONS:
        return -0.65
    if bare in {'活动', '活動', '服务', '服務', '应用', '應用'}:
        return -0.35
    if bare in {'管理', '事情'}:
        return -0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word = prefix.token_strings[-1].strip()
    value = chinese_activity(word)
    lower = word.lower()
    if lower in ENGLISH_ROUTINES:
        value = ENGLISH_ROUTINES[lower]
    elif lower == 'learning':
        value = -0.03 if previous in {'machine', 'deep', 'reinforcement'} else -0.35
    elif lower in {'life', 'lives'}:
        if previous in {'daily', 'everyday'}:
            value = -0.6
        elif previous == 'real':
            value = 0.27
        else:
            value = -0.03
    return (doc, lower), float(value)

