"""Approximate the strong positive response to aggregate-type vocabulary.

`struct` is strongest; enum, union, tuple and related names are weaker.
These are token matches, not parsed words: a fragment inside an ordinary
word may also fire. Case, attached whitespace/punctuation, and a few
immediate declaration/HTML contexts and "union of" change the strength.
Previous-token context is restricted to the current document. Other tokens
are approximated by zero, leaving diffuse positive/negative responses out.
"""
READS = ()

RELATED_TYPES = {
    'structs': 4.5, 'enums': 2.8, 'enumeration': 1.05,
    'enumerate': 0.45, 'tuple': 1.7, 'tuples': 1.5,
    'union': 2.4, 'unions': 1.8, 'typedef': 1.05,
    'array': 0.6, 'arrays': 0.75,
    'dict': 1.0, 'dictionary': 0.65, 'defaultdict': 0.8,
    'interface': 0.5, 'interfaces': 0.55,
    'static': 0.6, 'bool': 0.3, 'extern': 0.45,
    'protocol': 0.6, 'typename': 0.5,
    'structure': 0.6, 'structures': 0.7,
    'structural': 1.6, 'structured': 0.35,
    # Structure, array and union vocabulary in Chinese/Japanese.
    '结构': 1.1, '結構': 1.0, '構': 1.4, '构': 1.1, '数组': 1.0,
    '盟': 1.9, '联盟': 0.8,
}
HTML_TAGS = {'div', 'span', 'p', 'td', 'h1', 'h2', 'h3', 'h4'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('_(.<:/')
    lower = word.lower()
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    prev = previous.strip().lstrip('<').lower()
    value = RELATED_TYPES.get(lower, 0.0)

    if lower == 'struct':
        if word.isupper():
            value = 3.0
        elif word[0].isupper():
            value = 4.3
        elif raw.startswith('_'):
            value = 4.8
        else:
            value = 7.4 if raw.startswith('\t') else 6.3
            if raw == 'struct' and previous[-1:].isascii():
                if previous[-1:].isalpha():
                    value = 3.0  # Continuation, e.g. "in" + "struct".
            if prev in ('static', 'const', 'typedef'):
                value = 7.8
    elif lower == 'enum':
        value = 2.7 if word[0].isupper() or raw.startswith('_') else 4.2
        if raw[:1].isspace():
            value = 3.2 if word[0].isupper() else 4.8
        if word.isupper():
            value = 2.0
    elif lower == 'class':
        value = 0.2 if word[0].isupper() else 0.5
        if prev == 'static':
            value = 1.6
        elif prev in HTML_TAGS:
            value = 0.9
        elif prev == 'public':
            value = 0.3
    elif lower in ('array', 'dict') and raw.startswith(('_', '.')):
        value = 0.35
    elif lower == 'of' and prev in ('union', 'enum'):
        value = 0.85
    return None, value

