"""Fires on the end-of-text token and on tokens of C/C++ code: the _t of size_t or uint8_t,
the C type words (double, float, int, char, void, const, unsigned), and the C++ scaffolding
(std, cout, <<, ::, #include, .h). A token's leading space, tab, '(' , '*' or '&' is ignored,
so ' (double' counts as 'double'. Most other tokens, including ordinary prose, stay near zero."""

READS = ()

END_OF_TEXT = "<|endoftext|>"
STRONG = {"_t": 2.5, "double": 2.0, "cout": 2.0, "float": 1.5, "sizeof": 1.5, "#include": 1.5,
          ".h": 1.5, "namespace": 1.5, "uint8": 1.5, "uint32": 1.5, "fprintf": 1.3, "perror": 1.3}
WEAK = {"int": 1.0, "char": 0.6, "void": 0.6, "const": 0.6, "std": 1.0, "::": 0.8, "<<": 1.0,
        "unsigned": 1.0, "goto": 0.9, "include": 1.0}


def step(carry, prefix, upstream):
    s = prefix.token_strings[prefix.position].strip().lstrip("(*&")
    if prefix.token_strings[prefix.position] == END_OF_TEXT:
        return carry, 2.0
    if s in STRONG:
