VALUE_IDEOGRAPH_UTF8_LEAD = 19457  # E5 80, before the final byte of 値/值

# Related lexical classes, with progressively weaker responses than 'value'.
RELATED_WORDS = (
    (1.9, {'valued', 'valor', 'valore', 'valores', 'valeur', 'valeurs',
           'значение', 'значения', 'nilai', 'değer'}),
    (1.3, {'valuable', '价值', '價值', '的价值', '值得', '估值', '增值'}),
    (1.2, {'wert', 'warto', 'trị'}),
    (1.05, {'numeric', 'numerical'}),
    (0.85, {'key', 'keys', 'content', 'contents'}),
    (0.6, {'numbers', '内容', '內容', '颜值', '键', '鍵'}),
    (0.5, {'amount', 'amounts', 'element', 'elements', '元素'}),
    (0.45, {'data', '数据', '數據'}),
    (0.3, {'text', 'number'}),
)


def value_word(word, marker, space):
    plural = word.lower().endswith('s')
    if word.isupper():
        return (2.8 if plural else 4.1) + 0.3 * space
    if word.istitle():
        value = 4.2 if plural else 4.7 if space else 5.2
    else:
        value = (4.05 if space else 3.3) if plural else (4.45 if space else 4.3)
    if marker in {'.', '_'} and not plural:
        value -= 0.45 if marker == '.' and word.islower() else 0.15
    elif marker in {'(', '['}:
        value -= (0.8 if plural else 1.2) if word.islower() else 0.7
    elif marker == '<':
        value -= 1.2
    elif marker == '-' and word.islower():
        value += 0.3
    elif marker == '=':
        value -= 0.7
    return value


